package com.myproject.video.video_platform.service.product;

import com.fasterxml.jackson.core.JsonProcessingException;
import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.databind.node.ObjectNode;
import com.myproject.video.video_platform.common.converter.product.DownloadProductConverter;
import com.myproject.video.video_platform.common.converter.product.ProductConverter;
import com.myproject.video.video_platform.common.enums.products.ProductType;
import com.myproject.video.video_platform.common.enums.commerce.CommerceOrderStatus;
import com.myproject.video.video_platform.common.enums.entitlement.EntitlementSource;
import com.myproject.video.video_platform.common.enums.entitlement.EntitlementStatus;
import com.myproject.video.video_platform.dto.products.AbstractProductRequestDto;
import com.myproject.video.video_platform.dto.products.AbstractProductResponseDto;
import com.myproject.video.video_platform.dto.products.ProductMinimised;
import com.myproject.video.video_platform.dto.products.consultation.ConsultationProductRequestDto;
import com.myproject.video.video_platform.dto.products.course.CourseProductRequestDto;
import com.myproject.video.video_platform.dto.products.download.DownloadProductRequestDto;
import com.myproject.video.video_platform.dto.products.membership.MembershipProductRequestDto;
import com.myproject.video.video_platform.entity.products.Product;
import com.myproject.video.video_platform.entity.user.User;
import com.myproject.video.video_platform.exception.product.InvalidProductTypeException;
import com.myproject.video.video_platform.exception.product.ResourceNotFoundException;
import com.myproject.video.video_platform.exception.product.UnsupportedProductOperationException;
import com.myproject.video.video_platform.exception.user.UserNotFoundException;
import com.myproject.video.video_platform.repository.auth.UserRepository;
import com.myproject.video.video_platform.repository.commerce.CommerceOrderRepository;
import com.myproject.video.video_platform.repository.entitlement.ProductEntitlementRepository;
import com.myproject.video.video_platform.repository.products.ProductRepository;
import com.myproject.video.video_platform.repository.products.download.DownloadProductRepository;
import com.myproject.video.video_platform.repository.products.membership.MembershipFeedEntryRepository;
import com.myproject.video.video_platform.repository.products.membership.MembershipProductRepository;
import com.myproject.video.video_platform.service.admin.AdminAuditService;
import com.myproject.video.video_platform.service.product.strategy_handler.ProductTypeHandler;
import lombok.extern.slf4j.Slf4j;
import org.springframework.data.domain.Page;
import org.springframework.data.domain.Pageable;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.UUID;
import java.time.Instant;
import java.util.function.Function;
import java.util.stream.Collectors;

@Slf4j
@Service
public class ProductService {

    private final UserRepository userRepository;
    private final DownloadProductRepository downloadProductRepository;
    private final DownloadProductConverter downloadProductConverter;
    private final ProductRepository productRepository;
    private final Map<ProductType, ProductTypeHandler> handlers;
    private final ProductConverter productConverter;
    private final ObjectMapper objectMapper;
    private final ProductAuthorizationService productAuthorizationService;
    private final AdminAuditService adminAuditService;
    private final ProductEntitlementRepository entitlementRepository;
    private final CommerceOrderRepository commerceOrderRepository;
    private final MembershipFeedEntryRepository membershipFeedEntryRepository;
    private final MembershipProductRepository membershipProductRepository;
    private final ProductPresentationCleanupService presentationCleanupService;
    private final ProductMediaService productMediaService;

    public ProductService(UserRepository userRepository,
                          DownloadProductRepository downloadProductRepository,
                          DownloadProductConverter downloadProductConverter,
                          ProductRepository productRepository,
                          Set<ProductTypeHandler> handlerSet,
                          ProductConverter productConverter,
                          ObjectMapper objectMapper,
                          ProductAuthorizationService productAuthorizationService,
                          AdminAuditService adminAuditService,
                          ProductEntitlementRepository entitlementRepository,
                          CommerceOrderRepository commerceOrderRepository,
                          MembershipFeedEntryRepository membershipFeedEntryRepository,
                          MembershipProductRepository membershipProductRepository,
                          ProductPresentationCleanupService presentationCleanupService,
                          ProductMediaService productMediaService) {
        this.userRepository = userRepository;
        this.downloadProductRepository = downloadProductRepository;
        this.productRepository = productRepository;
        this.downloadProductConverter = downloadProductConverter;
        this.productConverter = productConverter;
        this.objectMapper = objectMapper;
        this.productAuthorizationService = productAuthorizationService;
        this.adminAuditService = adminAuditService;
        this.entitlementRepository = entitlementRepository;
        this.commerceOrderRepository = commerceOrderRepository;
        this.membershipFeedEntryRepository = membershipFeedEntryRepository;
        this.membershipProductRepository = membershipProductRepository;
        this.presentationCleanupService = presentationCleanupService;
        this.productMediaService = productMediaService;

        // Convert the set of handlers into a map: ProductType -> handler
        this.handlers = handlerSet.stream()
                .collect(Collectors.toMap(
                        ProductTypeHandler::getSupportedType,
                        Function.identity()
                ));
    }


    public AbstractProductResponseDto createProduct(AbstractProductRequestDto dto) {
        AbstractProductResponseDto response = getProductStrategyHandler(dto.getType()).createProduct(dto);
        recordAdminProductAction("PRODUCT_CREATE", null, response);
        return enrich(response);
    }


    public AbstractProductResponseDto getProductByIdAndType(String productId, String type) {
        return enrich(getProductStrategyHandler(type).getProductById(productId));
    }

    public AbstractProductResponseDto getProductById(String productId) {
        Product product = getProductEntity(productId);
        return enrich(getProductStrategyHandler(product.getType().name()).getProductById(product.getId().toString()));
    }

    public AbstractProductResponseDto updateProduct(AbstractProductRequestDto dto) {
        Product before = getProductEntity(dto.getId());
        String beforeSummary = productSummary(before);
        AbstractProductResponseDto response = getProductStrategyHandler(dto.getType()).updateProduct(dto);
        recordAdminProductAction("PRODUCT_UPDATE", beforeSummary, response);
        return enrich(response);
    }

    public AbstractProductResponseDto patchProduct(String productId, JsonNode payload) {
        Product product = getProductEntity(productId);
        String beforeSummary = productSummary(product);
        AbstractProductRequestDto dto = mapPatchPayload(product, payload);
        AbstractProductResponseDto response = getProductStrategyHandler(product.getType().name()).updateProduct(dto);
        recordAdminProductAction("PRODUCT_UPDATE", beforeSummary, response);
        return enrich(response);
    }

    public List<AbstractProductResponseDto> getAllProductsForUser(String userId) {
        User user = userRepository.findByUserId(UUID.fromString(userId))
                .orElseThrow(() -> new UserNotFoundException("User not found with id: " + userId));

        List<Product> products = productRepository.findAllByUser(user);

        return products.stream()
                .map(product -> getProductStrategyHandler(product.getType().name())
                        .getProductById(product.getId().toString()))
                .map(this::enrich)
                .toList();
    }


    private ProductTypeHandler getProductStrategyHandler(String typeStr) {
        ProductType type;

        try {
            type = ProductType.valueOf(typeStr.toUpperCase());
        } catch (IllegalArgumentException e) {
            throw new InvalidProductTypeException("Unknown product type: " + typeStr);
        }

        ProductTypeHandler handler = handlers.get(type);
        if (handler == null) {
            throw new InvalidProductTypeException("No handler for product type: " + type);
        }
        return handler;
    }


    @Transactional
    public void deleteProduct(String userId, String productId, String productType) {
        Product before = getProductEntity(productId);
        requireProductCanBeDeleted(before.getId());
        String beforeSummary = productSummary(before);
        entitlementRepository.deleteAllByProductId(before.getId());
        removeMembershipReferences(before.getId());
        presentationCleanupService.removeProductReferences(before.getId());
        productMediaService.removeAll(before.getId());
        getProductStrategyHandler(productType).deleteProduct(userId, productId);
        recordAdminProductAction("PRODUCT_DELETE", beforeSummary, before.getId().toString(), before.getUser().getUserId().toString(), null);
    }

    @Transactional
    public void deleteProductById(String productId) {
        Product product = getProductEntity(productId);
        requireProductCanBeDeleted(product.getId());
        String beforeSummary = productSummary(product);
        entitlementRepository.deleteAllByProductId(product.getId());
        removeMembershipReferences(product.getId());
        presentationCleanupService.removeProductReferences(product.getId());
        productMediaService.removeAll(product.getId());
        getProductStrategyHandler(product.getType().name())
                .deleteProduct(product.getUser().getUserId().toString(), product.getId().toString());
        recordAdminProductAction("PRODUCT_DELETE", beforeSummary, product.getId().toString(), product.getUser().getUserId().toString(), null);
    }

    private void requireProductCanBeDeleted(UUID productId) {
        boolean hasActivePurchase = entitlementRepository.existsByProductIdAndStatusAndSource(
                productId,
                EntitlementStatus.ACTIVE,
                EntitlementSource.PURCHASE
        );
        boolean hasLiveCheckout = commerceOrderRepository.existsLivePendingOrderForProduct(
                productId,
                CommerceOrderStatus.PENDING,
                Instant.now()
        );
        if (hasActivePurchase || hasLiveCheckout) {
            throw new UnsupportedProductOperationException(
                    "Products with active purchases or checkout sessions cannot be deleted; hide the Product instead"
            );
        }
    }

    private void removeMembershipReferences(UUID productId) {
        List<UUID> membershipIds = membershipFeedEntryRepository.findMembershipIdsByIncludedProductId(productId);
        membershipFeedEntryRepository.deleteAllByIncludedProductId(productId);
        membershipIds.forEach(id -> membershipProductRepository.findById(id).ifPresent(membership -> {
            membership.setUpdatedAt(java.time.LocalDateTime.now());
            membershipProductRepository.save(membership);
        }));
    }

    private AbstractProductResponseDto enrich(AbstractProductResponseDto response) {
        if (response != null && response.getId() != null) {
            productMediaService.enrich(response.getId(), response);
        }
        return response;
    }

    public List<ProductMinimised> getAllProductsMinimised() {
        List<Product> products = productRepository.findAll();

        return products.stream()
                .map(productConverter::mapProductMinimisedToResponse)
                .toList();
    }

    public List<ProductMinimised> getAllProductsMinimisedForUser(String userId) {
        User user = userRepository.findByUserId(UUID.fromString(userId))
                .orElseThrow(() -> new UserNotFoundException("User not found: " + userId));

        List<Product> products = productRepository.findAllByUser(user);

        return products.stream()
                .map(productConverter::mapProductMinimisedToResponse)
                .toList();
    }

    public List<ProductMinimised> getProductSummariesForOwner(String ownerId) {
        return getAllProductsMinimisedForUser(ownerId);
    }

    /** EXPLORE: all products by name or owner */
    public Page<ProductMinimised> searchAllProducts(String term, Pageable pageable) {
        String normalized = term.trim().toLowerCase();
        return productRepository.searchByNameOrOwner(normalized, pageable)
                .map(productConverter::mapProductMinimisedToResponse);
    }

    /** LIBRARY/TEACHER: this user’s products by name */
    public Page<ProductMinimised> searchUserProducts(String userIdStr, String term, Pageable pageable) {
        UUID userId = UUID.fromString(userIdStr);

        userRepository.findByUserId(userId)
                .orElseThrow(() -> new UserNotFoundException("User not found: " + userIdStr));

        String normalized = term.trim().toLowerCase();
        return productRepository.searchByUserAndName(userId, normalized, pageable)
                .map(productConverter::mapProductMinimisedToResponse);
    }

    private Product getProductEntity(String productId) {
        UUID id = UUID.fromString(productId);
        return productRepository.findById(id)
                .orElseThrow(() -> new ResourceNotFoundException("Product not found: " + productId));
    }

    private void recordAdminProductAction(String action, String beforeSummary, AbstractProductResponseDto response) {
        if (!productAuthorizationService.isCurrentUserAdmin()) {
            return;
        }
        recordAdminProductAction(
                action,
                beforeSummary,
                response.getId().toString(),
                response.getUserId().toString(),
                responseSummary(response)
        );
    }

    private void recordAdminProductAction(String action,
                                          String beforeSummary,
                                          String productId,
                                          String ownerId,
                                          String afterSummary) {
        if (!productAuthorizationService.isCurrentUserAdmin()) {
            return;
        }
        adminAuditService.recordCurrentAdminAction(
                action,
                "PRODUCT",
                productId,
                beforeSummary,
                afterSummary != null ? afterSummary : "ownerId=" + ownerId
        );
    }

    private String productSummary(Product product) {
        return "id=%s,type=%s,name=%s,status=%s,ownerId=%s".formatted(
                product.getId(),
                product.getType(),
                product.getName(),
                product.getStatus(),
                product.getUser().getUserId()
        );
    }

    private String responseSummary(AbstractProductResponseDto response) {
        return "id=%s,type=%s,name=%s,status=%s,ownerId=%s".formatted(
                response.getId(),
                response.getType(),
                response.getName(),
                response.getStatus(),
                response.getUserId()
        );
    }

    private AbstractProductRequestDto mapPatchPayload(Product product, JsonNode payload) {
        ObjectNode objectNode = payload != null && payload.isObject()
                ? ((ObjectNode) payload).deepCopy()
                : objectMapper.createObjectNode();

        objectNode.put("id", product.getId().toString());
        objectNode.put("type", product.getType().name());

        if (!objectNode.hasNonNull("userId")) {
            objectNode.put("userId", product.getUser().getUserId().toString());
        }

        Class<? extends AbstractProductRequestDto> dtoClass = switch (product.getType()) {
            case COURSE -> CourseProductRequestDto.class;
            case DOWNLOAD -> DownloadProductRequestDto.class;
            case CONSULTATION -> ConsultationProductRequestDto.class;
            case MEMBERSHIP -> MembershipProductRequestDto.class;
        };

        try {
            AbstractProductRequestDto dto = objectMapper.treeToValue(objectNode, dtoClass);
            if (dto instanceof DownloadProductRequestDto downloadDto) {
                downloadDto.setDetails(null);
            }
            if (dto instanceof CourseProductRequestDto courseDto) {
                courseDto.setDetails(null);
            }
            return dto;
        } catch (JsonProcessingException e) {
            throw new InvalidProductTypeException("Invalid product patch payload: " + e.getOriginalMessage());
        }
    }
}

package com.myproject.video.video_platform.service.product;

import com.myproject.video.video_platform.common.enums.products.ProductType;
import com.myproject.video.video_platform.dto.products.authoring.ProductSectionCreateRequestDto;
import com.myproject.video.video_platform.dto.products.authoring.ProductSectionResponseDto;
import com.myproject.video.video_platform.dto.products.authoring.ProductSectionUpdateRequestDto;
import com.myproject.video.video_platform.dto.products.course.CourseLessonResponseDto;
import com.myproject.video.video_platform.dto.products.download.FileDownloadProductResponseDto;
import com.myproject.video.video_platform.entity.products.Product;
import com.myproject.video.video_platform.entity.products.course.CourseLesson;
import com.myproject.video.video_platform.entity.products.course.CourseProduct;
import com.myproject.video.video_platform.entity.products.course.CourseSection;
import com.myproject.video.video_platform.entity.products.download.DownloadProduct;
import com.myproject.video.video_platform.entity.products.download.FileDownloadProduct;
import com.myproject.video.video_platform.entity.products.download.SectionDownloadProduct;
import com.myproject.video.video_platform.exception.product.ResourceNotFoundException;
import com.myproject.video.video_platform.exception.product.UnsupportedProductOperationException;
import com.myproject.video.video_platform.repository.products.ProductRepository;
import com.myproject.video.video_platform.repository.products.course.CourseProductRepository;
import com.myproject.video.video_platform.repository.products.course.CourseSectionRepository;
import com.myproject.video.video_platform.repository.products.download.DownloadProductRepository;
import com.myproject.video.video_platform.repository.products.download.SectionDownloadProductRepository;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import java.time.LocalDateTime;
import java.util.Comparator;
import java.util.List;
import java.util.UUID;

@Service
@Slf4j
@RequiredArgsConstructor
public class ProductSectionService {

    @Value("${digitalocean.spaces.cdnEndpointUrl}")
    private String cdnEndpointUrl;

    @Value("${digitalocean.spaces.bucket-media}")
    private String mediaBucket;

    private final ProductRepository productRepository;
    private final CourseProductRepository courseProductRepository;
    private final DownloadProductRepository downloadProductRepository;
    private final CourseSectionRepository courseSectionRepository;
    private final SectionDownloadProductRepository downloadSectionRepository;
    private final ProductAuthorizationService productAuthorizationService;

    @Transactional
    public ProductSectionResponseDto createSection(String productId, ProductSectionCreateRequestDto dto) {
        Product product = getOwnedProduct(productId);

        return switch (product.getType()) {
            case COURSE -> createCourseSection(product.getId(), dto);
            case DOWNLOAD -> createDownloadSection(product.getId(), dto);
            case CONSULTATION -> throw unsupported("Sections are not supported for CONSULTATION products.");
            case MEMBERSHIP -> throw unsupported("Sections are managed through the Membership feed API.");
        };
    }

    @Transactional
    public ProductSectionResponseDto updateSection(
            String productId,
            String sectionId,
            ProductSectionUpdateRequestDto dto
    ) {
        Product product = getOwnedProduct(productId);

        return switch (product.getType()) {
            case COURSE -> updateCourseSection(product.getId(), sectionId, dto);
            case DOWNLOAD -> updateDownloadSection(product.getId(), sectionId, dto);
            case CONSULTATION -> throw unsupported("Sections are not supported for CONSULTATION products.");
            case MEMBERSHIP -> throw unsupported("Sections are managed through the Membership feed API.");
        };
    }

    @Transactional
    public void deleteSection(String productId, String sectionId) {
        Product product = getOwnedProduct(productId);

        switch (product.getType()) {
            case COURSE -> deleteCourseSection(product.getId(), sectionId);
            case DOWNLOAD -> deleteDownloadSection(product.getId(), sectionId);
            case CONSULTATION -> throw unsupported("Sections are not supported for CONSULTATION products.");
            case MEMBERSHIP -> throw unsupported("Sections are managed through the Membership feed API.");
        }
    }

    @Transactional(readOnly = true)
    public ProductSectionResponseDto getSection(String productId, String sectionId) {
        Product product = getOwnedProduct(productId);

        return switch (product.getType()) {
            case COURSE -> mapCourseSection(loadCourseSection(product.getId(), sectionId));
            case DOWNLOAD -> mapDownloadSection(loadDownloadSection(product.getId(), sectionId));
            case CONSULTATION -> throw unsupported("Sections are not supported for CONSULTATION products.");
            case MEMBERSHIP -> throw unsupported("Sections are managed through the Membership feed API.");
        };
    }

    private ProductSectionResponseDto createCourseSection(UUID productId, ProductSectionCreateRequestDto dto) {
        CourseProduct course = courseProductRepository.findFullById(productId)
                .orElseThrow(() -> new ResourceNotFoundException("Course not found: " + productId));

        CourseSection section = new CourseSection();
        section.setTitle(dto.getTitle());
        section.setDescription(dto.getDescription());
        section.setPosition(resolvePosition(dto.getPosition(), course.getSections().size()));
        section.setCourse(course);

        course.getSections().add(section);
        CourseSection saved = courseSectionRepository.save(section);
        touchCourse(course);
        return mapCourseSection(saved);
    }

    private ProductSectionResponseDto updateCourseSection(
            UUID productId,
            String sectionId,
            ProductSectionUpdateRequestDto dto
    ) {
        CourseSection section = loadCourseSection(productId, sectionId);

        if (dto.getTitle() != null) {
            section.setTitle(dto.getTitle());
        }
        if (dto.getDescription() != null) {
            section.setDescription(dto.getDescription());
        }
        if (dto.getPosition() != null) {
            section.setPosition(dto.getPosition());
        }

        CourseSection saved = courseSectionRepository.save(section);
        touchCourse(section.getCourse());
        return mapCourseSection(saved);
    }

    private void deleteCourseSection(UUID productId, String sectionId) {
        CourseSection section = loadCourseSection(productId, sectionId);
        CourseProduct course = section.getCourse();
        courseSectionRepository.delete(section);
        touchCourse(course);
    }

    private ProductSectionResponseDto createDownloadSection(UUID productId, ProductSectionCreateRequestDto dto) {
        DownloadProduct product = downloadProductRepository.findFullById(productId)
                .orElseThrow(() -> new ResourceNotFoundException("Download product not found: " + productId));

        SectionDownloadProduct section = new SectionDownloadProduct();
        section.setTitle(dto.getTitle());
        section.setDescription(dto.getDescription());
        section.setPosition(resolvePosition(dto.getPosition(), product.getSectionDownloadProducts().size()));
        section.setDownloadProduct(product);

        product.getSectionDownloadProducts().add(section);
        SectionDownloadProduct saved = downloadSectionRepository.save(section);
        touchDownloadProduct(product);
        return mapDownloadSection(saved);
    }

    private ProductSectionResponseDto updateDownloadSection(
            UUID productId,
            String sectionId,
            ProductSectionUpdateRequestDto dto
    ) {
        SectionDownloadProduct section = loadDownloadSection(productId, sectionId);

        if (dto.getTitle() != null) {
            section.setTitle(dto.getTitle());
        }
        if (dto.getDescription() != null) {
            section.setDescription(dto.getDescription());
        }
        if (dto.getPosition() != null) {
            section.setPosition(dto.getPosition());
        }

        SectionDownloadProduct saved = downloadSectionRepository.save(section);
        touchDownloadProduct(section.getDownloadProduct());
        return mapDownloadSection(saved);
    }

    private void deleteDownloadSection(UUID productId, String sectionId) {
        SectionDownloadProduct section = loadDownloadSection(productId, sectionId);
        DownloadProduct product = section.getDownloadProduct();
        downloadSectionRepository.delete(section);
        touchDownloadProduct(product);
    }

    private CourseSection loadCourseSection(UUID productId, String sectionId) {
        CourseSection section = courseSectionRepository.findById(UUID.fromString(sectionId))
                .orElseThrow(() -> new ResourceNotFoundException("Section not found: " + sectionId));

        if (!section.getCourse().getId().equals(productId)) {
            throw new ResourceNotFoundException(
                    "Section not found for course " + productId + ": " + sectionId
            );
        }

        return section;
    }

    private SectionDownloadProduct loadDownloadSection(UUID productId, String sectionId) {
        SectionDownloadProduct section = downloadSectionRepository.findById(UUID.fromString(sectionId))
                .orElseThrow(() -> new ResourceNotFoundException("Section not found: " + sectionId));

        if (!section.getDownloadProduct().getId().equals(productId)) {
            throw new ResourceNotFoundException(
                    "Section not found for download product " + productId + ": " + sectionId
            );
        }

        return section;
    }

    private Product getOwnedProduct(String productId) {
        Product product = productRepository.findById(UUID.fromString(productId))
                .orElseThrow(() -> new ResourceNotFoundException("Product not found: " + productId));

        productAuthorizationService.requireOwnerOrAdmin(product);

        return product;
    }

    private ProductSectionResponseDto mapCourseSection(CourseSection section) {
        ProductSectionResponseDto dto = new ProductSectionResponseDto();
        dto.setId(section.getId().toString());
        dto.setProductId(section.getCourse().getId().toString());
        dto.setTitle(section.getTitle());
        dto.setDescription(section.getDescription());
        dto.setPosition(section.getPosition());
        dto.setLessons(section.getLessons() == null
                ? List.of()
                : section.getLessons().stream()
                .sorted(Comparator.comparing(CourseLesson::getPosition, Comparator.nullsLast(Integer::compareTo)))
                .map(this::mapLesson)
                .toList());
        return dto;
    }

    private ProductSectionResponseDto mapDownloadSection(SectionDownloadProduct section) {
        ProductSectionResponseDto dto = new ProductSectionResponseDto();
        dto.setId(section.getId().toString());
        dto.setProductId(section.getDownloadProduct().getId().toString());
        dto.setTitle(section.getTitle());
        dto.setDescription(section.getDescription());
        dto.setPosition(section.getPosition());
        dto.setFiles(section.getFiles() == null
                ? List.of()
                : section.getFiles().stream()
                .sorted(Comparator.comparing(FileDownloadProduct::getUploadedAt, Comparator.nullsLast(LocalDateTime::compareTo)))
                .map(this::mapFile)
                .toList());
        return dto;
    }

    private CourseLessonResponseDto mapLesson(CourseLesson lesson) {
        CourseLessonResponseDto dto = new CourseLessonResponseDto();
        dto.setId(lesson.getId().toString());
        dto.setTitle(lesson.getTitle());
        dto.setType(lesson.getType().name());
        dto.setVideoUrl(lesson.getVideoUrl());
        dto.setContent(lesson.getContent());
        dto.setDescription(lesson.getDescription());
        dto.setPosition(lesson.getPosition());
        dto.setSectionId(lesson.getSection().getId().toString());
        return dto;
    }

    private FileDownloadProductResponseDto mapFile(FileDownloadProduct file) {
        FileDownloadProductResponseDto dto = new FileDownloadProductResponseDto();
        dto.setId(file.getId());
        dto.setFileName(file.getFileName());
        dto.setSize(file.getSize());
        dto.setFileType(file.getFileType());
        dto.setUrl(String.format("%s/%s/%s", cdnEndpointUrl, mediaBucket, file.getPath()));
        return dto;
    }

    private void touchCourse(CourseProduct course) {
        course.setUpdatedAt(LocalDateTime.now());
        courseProductRepository.save(course);
    }

    private void touchDownloadProduct(DownloadProduct product) {
        product.setUpdatedAt(LocalDateTime.now());
        downloadProductRepository.save(product);
    }

    private int resolvePosition(Integer requestedPosition, int existingCount) {
        return requestedPosition != null ? requestedPosition : existingCount + 1;
    }

    private UnsupportedProductOperationException unsupported(String message) {
        return new UnsupportedProductOperationException(message);
    }
}

package com.myproject.video.video_platform.service.product.course;

import com.myproject.video.video_platform.common.enums.products.course.LessonType;
import com.myproject.video.video_platform.common.enums.products.ProductType;
import com.myproject.video.video_platform.dto.products.authoring.ProductLessonCreateRequestDto;
import com.myproject.video.video_platform.dto.products.authoring.ProductLessonUpdateRequestDto;
import com.myproject.video.video_platform.dto.products.course.CourseLessonCreateRequestDto;
import com.myproject.video.video_platform.dto.products.course.CourseLessonResponseDto;
import com.myproject.video.video_platform.dto.products.course.CourseLessonUpdateRequestDto;
import com.myproject.video.video_platform.entity.products.Product;
import com.myproject.video.video_platform.entity.products.course.CourseProduct;
import com.myproject.video.video_platform.entity.products.course.CourseLesson;
import com.myproject.video.video_platform.entity.products.course.CourseSection;
import com.myproject.video.video_platform.exception.product.ResourceNotFoundException;
import com.myproject.video.video_platform.exception.product.UnsupportedProductOperationException;
import com.myproject.video.video_platform.repository.products.ProductRepository;
import com.myproject.video.video_platform.repository.products.course.CourseProductRepository;
import com.myproject.video.video_platform.repository.products.course.CourseLessonRepository;
import com.myproject.video.video_platform.repository.products.course.CourseSectionRepository;
import com.myproject.video.video_platform.service.product.ProductAuthorizationService;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import java.time.LocalDateTime;
import java.util.Optional;
import java.util.UUID;

@Service
@Slf4j
@RequiredArgsConstructor
public class CourseLessonService {

    private final ProductRepository productRepository;
    private final CourseProductRepository courseRepo;
    private final CourseSectionRepository sectionRepo;
    private final CourseLessonRepository lessonRepo;
    private final ProductAuthorizationService productAuthorizationService;

    /**
     * POST /api/sections/{sectionId}/lessons
     */
    @Transactional
    public CourseLessonResponseDto createLesson(CourseLessonCreateRequestDto dto) {

        UUID sectionId = UUID.fromString(dto.getSectionId());
        CourseSection section = sectionRepo.findById(sectionId)
                .orElseThrow(() -> new ResourceNotFoundException("Section not found: " + sectionId));

        productAuthorizationService.requireOwnerOrAdmin(section.getCourse());

        CourseLesson lesson = new CourseLesson();
        lesson.setTitle(dto.getTitle());
        LessonType lessonType = LessonType.valueOf(dto.getType().toUpperCase());
        lesson.setType(lessonType);
        applyLessonContent(lesson, lessonType, dto.getVideoUrl(), dto.getContent());
        lesson.setDescription(dto.getDescription());
        lesson.setPosition(
                dto.getPosition() == null
                        ? section.getLessons().size() + 1
                        : dto.getPosition()
        );
        lesson.setSection(section);

        section.getLessons().add(lesson);
        lessonRepo.save(lesson); // cascade saves lesson
        touchProductUpdatedAt(section.getCourse());

        CourseLessonResponseDto resp = new CourseLessonResponseDto();
        resp.setId(lesson.getId().toString());
        resp.setTitle(lesson.getTitle());
        resp.setType(lesson.getType().name());
        resp.setVideoUrl(lesson.getVideoUrl());
        resp.setContent(lesson.getContent());
        resp.setDescription(lesson.getDescription());
        resp.setPosition(lesson.getPosition());
        resp.setSectionId(section.getId().toString());
        return resp;
    }

    /**
     * PUT /api/lessons/{lessonId}
     */
    @Transactional
    public void updateLesson(CourseLessonUpdateRequestDto dto) {
        UUID lessonId = UUID.fromString(dto.getId());
        CourseLesson lesson = lessonRepo.findById(lessonId)
                .orElseThrow(() -> new ResourceNotFoundException("Lesson not found: " + dto.getId()));

        productAuthorizationService.requireOwnerOrAdmin(lesson.getSection().getCourse());

        lesson.setTitle(dto.getTitle());
        LessonType newType = LessonType.valueOf(dto.getType().toUpperCase());
        lesson.setType(newType);
        applyLessonContent(lesson, newType, dto.getVideoUrl(), dto.getContent());
        lesson.setDescription(dto.getDescription());
        if (dto.getPosition() != null) {
            lesson.setPosition(dto.getPosition());
        }
        lessonRepo.save(lesson);
        touchProductUpdatedAt(lesson.getSection().getCourse());
    }

    @Transactional
    public CourseLessonResponseDto createLesson(
            String productId,
            String sectionId,
            ProductLessonCreateRequestDto dto
    ) {
        Product product = loadOwnedProduct(productId);
        if (product.getType() != ProductType.COURSE) {
            throw new UnsupportedProductOperationException("Lessons are only supported for COURSE products.");
        }

        CourseSection section = loadOwnedSection(product.getId(), sectionId);

        CourseLesson lesson = new CourseLesson();
        lesson.setTitle(dto.getTitle());
        LessonType lessonType = LessonType.valueOf(dto.getType().toUpperCase());
        lesson.setType(lessonType);
        applyLessonContent(lesson, lessonType, dto.getVideoUrl(), dto.getContent());
        lesson.setDescription(dto.getDescription());
        lesson.setPosition(
                dto.getPosition() == null
                        ? section.getLessons().size() + 1
                        : dto.getPosition()
        );
        lesson.setSection(section);

        section.getLessons().add(lesson);
        CourseLesson saved = lessonRepo.save(lesson);
        touchProductUpdatedAt(section.getCourse());
        return mapLesson(saved);
    }

    @Transactional
    public CourseLessonResponseDto updateLesson(
            String productId,
            String sectionId,
            String lessonId,
            ProductLessonUpdateRequestDto dto
    ) {
        Product product = loadOwnedProduct(productId);
        if (product.getType() != ProductType.COURSE) {
            throw new UnsupportedProductOperationException("Lessons are only supported for COURSE products.");
        }

        CourseSection section = loadOwnedSection(product.getId(), sectionId);
        CourseLesson lesson = loadLesson(section.getId(), lessonId);

        if (dto.getTitle() != null) {
            lesson.setTitle(dto.getTitle());
        }

        LessonType effectiveType = lesson.getType();
        if (dto.getType() != null) {
            effectiveType = LessonType.valueOf(dto.getType().toUpperCase());
            lesson.setType(effectiveType);
            applyLessonContent(lesson, effectiveType, dto.getVideoUrl(), dto.getContent());
        } else if (effectiveType == LessonType.VIDEO && dto.getVideoUrl() != null) {
            lesson.setVideoUrl(dto.getVideoUrl());
        } else if (effectiveType == LessonType.ARTICLE && dto.getContent() != null) {
            lesson.setContent(dto.getContent());
        }

        if (dto.getDescription() != null) {
            lesson.setDescription(dto.getDescription());
        }
        if (dto.getPosition() != null) {
            lesson.setPosition(dto.getPosition());
        }

        CourseLesson saved = lessonRepo.save(lesson);
        touchProductUpdatedAt(section.getCourse());
        return mapLesson(saved);
    }

    @Transactional
    public void deleteLesson(String productId, String sectionId, String lessonId) {
        Product product = loadOwnedProduct(productId);
        if (product.getType() != ProductType.COURSE) {
            throw new UnsupportedProductOperationException("Lessons are only supported for COURSE products.");
        }

        CourseSection section = loadOwnedSection(product.getId(), sectionId);
        CourseLesson lesson = loadLesson(section.getId(), lessonId);

        CourseProduct course = lesson.getSection().getCourse();
        lessonRepo.delete(lesson);
        touchProductUpdatedAt(course);
    }

public void deleteLesson(String userId, String lessonId) {
        Optional<CourseLesson> lessonOptional = lessonRepo.findById(UUID.fromString(lessonId));
        if (lessonOptional.isPresent()) {
            productAuthorizationService.requireOwnerOrAdmin(lessonOptional.get().getSection().getCourse());

            CourseProduct course = lessonOptional.get().getSection().getCourse();
            lessonRepo.delete(lessonOptional.get());
            touchProductUpdatedAt(course);
            log.info("Deleted succesfully a Course lesson: {}", lessonId);
        } else
            throw new ResourceNotFoundException("Course lesson not found for ID: " + lessonId);

}

    private Product loadOwnedProduct(String productId) {
        Product product = productRepository.findById(UUID.fromString(productId))
                .orElseThrow(() -> new ResourceNotFoundException("Product not found: " + productId));

        productAuthorizationService.requireOwnerOrAdmin(product);
        return product;
    }

    private CourseSection loadOwnedSection(UUID productId, String sectionId) {
        CourseSection section = sectionRepo.findById(UUID.fromString(sectionId))
                .orElseThrow(() -> new ResourceNotFoundException("Section not found: " + sectionId));

        if (!section.getCourse().getId().equals(productId)) {
            throw new ResourceNotFoundException(
                    "Section not found for course " + productId + ": " + sectionId
            );
        }
        return section;
    }

    private CourseLesson loadLesson(UUID sectionId, String lessonId) {
        CourseLesson lesson = lessonRepo.findById(UUID.fromString(lessonId))
                .orElseThrow(() -> new ResourceNotFoundException("Lesson not found: " + lessonId));

        if (!lesson.getSection().getId().equals(sectionId)) {
            throw new ResourceNotFoundException(
                    "Lesson not found for section " + sectionId + ": " + lessonId
            );
        }
        return lesson;
    }

    private CourseLessonResponseDto mapLesson(CourseLesson lesson) {
        CourseLessonResponseDto dto = new CourseLessonResponseDto();
        dto.setId(lesson.getId().toString());
        dto.setTitle(lesson.getTitle());
        dto.setType(lesson.getType().name());
        dto.setVideoUrl(lesson.getVideoUrl());
        dto.setContent(lesson.getContent());
        dto.setDescription(lesson.getDescription());
        dto.setPosition(lesson.getPosition());
        dto.setSectionId(lesson.getSection().getId().toString());
        return dto;
    }

    private void applyLessonContent(CourseLesson lesson, LessonType type, String videoUrl, String content) {
        switch (type) {
            case VIDEO -> {
                lesson.setVideoUrl(videoUrl);
                lesson.setContent(null);
            }
            case ARTICLE -> {
                lesson.setContent(content);
                lesson.setVideoUrl(null);
            }
            case QUIZ -> {
                lesson.setVideoUrl(null);
                lesson.setContent(null);
            }
        }
    }

    private void touchProductUpdatedAt(CourseProduct course) {
        course.setUpdatedAt(LocalDateTime.now());
        courseRepo.save(course);
    }
}

package com.myproject.video.video_platform.service.product.course.quiz;

import com.myproject.video.video_platform.common.enums.products.course.LessonType;
import com.myproject.video.video_platform.dto.products.course.quiz.QuizDraftDto;
import com.myproject.video.video_platform.entity.products.course.CourseLesson;
import com.myproject.video.video_platform.entity.products.course.CourseProduct;
import com.myproject.video.video_platform.entity.products.course.quiz.Quiz;
import com.myproject.video.video_platform.exception.product.QuizValidationException;
import com.myproject.video.video_platform.exception.product.ResourceNotFoundException;
import com.myproject.video.video_platform.repository.products.course.CourseProductRepository;
import com.myproject.video.video_platform.repository.products.course.CourseLessonRepository;
import com.myproject.video.video_platform.repository.products.course.quiz.QuizRepository;
import com.myproject.video.video_platform.service.product.ProductAuthorizationService;
import lombok.RequiredArgsConstructor;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import java.util.Map;
import java.time.LocalDateTime;
import java.util.UUID;

@Service
@RequiredArgsConstructor
public class LessonQuizAuthoringService {

    private final CourseLessonRepository lessonRepository;
    private final CourseProductRepository courseRepository;
    private final QuizRepository quizRepository;
    private final ProductAuthorizationService productAuthorizationService;
    private final QuizValidator quizValidator;
    private final QuizMapper quizMapper;

    @Transactional(readOnly = true)
    public QuizDraftDto getQuiz(UUID lessonId) {
        CourseLesson lesson = requireLesson(lessonId);
        ensureOwner(lesson);
        ensureQuizLesson(lesson);

        Quiz quiz = lesson.getQuiz();
        if (quiz == null) {
            throw new ResourceNotFoundException("Quiz not found for lesson " + lessonId);
        }
        return quizMapper.toAuthoringDto(quiz);
    }

    @Transactional
    public QuizDraftDto upsertQuiz(UUID lessonId, QuizDraftDto dto) {
        CourseLesson lesson = requireLesson(lessonId);
        ensureOwner(lesson);
        ensureQuizLesson(lesson);
        quizValidator.validateDraft(dto);

        Quiz quiz = lesson.getQuiz();
        if (quiz != null && dto.getId() != null && !quiz.getId().toString().equals(dto.getId())) {
            throw new QuizValidationException("Quiz identifier mismatch", Map.of(
                    "id", "Existing quiz id does not match payload")
            );
        }
        if (quiz == null) {
            quiz = new Quiz();
        }
        quizMapper.applyDraft(quiz, dto, lesson);
        Quiz saved = quizRepository.save(quiz);
        lesson.setQuiz(saved);
        lesson.setUpdatedAt(LocalDateTime.now());
        lessonRepository.save(lesson);
        touchProductUpdatedAt(lesson.getSection().getCourse());
        return quizMapper.toAuthoringDto(saved);
    }

    @Transactional
    public void deleteQuiz(UUID lessonId) {
        CourseLesson lesson = requireLesson(lessonId);
        ensureOwner(lesson);
        ensureQuizLesson(lesson);

        Quiz quiz = lesson.getQuiz();
        if (quiz == null) {
            throw new ResourceNotFoundException("Quiz not found for lesson " + lessonId);
        }
        lesson.setQuiz(null);
        lesson.setUpdatedAt(LocalDateTime.now());
        lessonRepository.save(lesson);
        quizRepository.delete(quiz);
        touchProductUpdatedAt(lesson.getSection().getCourse());
    }

    private CourseLesson requireLesson(UUID lessonId) {
        return lessonRepository.findById(lessonId)
                .orElseThrow(() -> new ResourceNotFoundException("Lesson not found: " + lessonId));
    }

    private void ensureOwner(CourseLesson lesson) {
        productAuthorizationService.requireOwnerOrAdmin(lesson.getSection().getCourse());
    }

    private void ensureQuizLesson(CourseLesson lesson) {
        if (lesson.getType() != LessonType.QUIZ) {
            throw new QuizValidationException("Lesson does not support quizzes", Map.of(
                    "lessonId", "Lesson is not of type QUIZ")
            );
        }
    }

    private void touchProductUpdatedAt(CourseProduct course) {
        course.setUpdatedAt(LocalDateTime.now());
        courseRepository.save(course);
    }
}

package com.myproject.video.video_platform.service.product;

import com.myproject.video.video_platform.common.enums.s3folders.S3UploadFolder;
import com.myproject.video.video_platform.common.enums.products.ProductType;
import com.myproject.video.video_platform.dto.s3_files.ConfirmUploadRequestDto;
import com.myproject.video.video_platform.dto.s3_files.FileS3UploadResponseDto;
import com.myproject.video.video_platform.dto.s3_files.PresignedUrlResponseDto;
import com.myproject.video.video_platform.entity.products.Product;
import com.myproject.video.video_platform.entity.products.download.FileDownloadProduct;
import com.myproject.video.video_platform.entity.products.download.SectionDownloadProduct;
import com.myproject.video.video_platform.exception.product.ResourceNotFoundException;
import com.myproject.video.video_platform.exception.product.UnsupportedProductOperationException;
import com.myproject.video.video_platform.repository.products.ProductRepository;
import com.myproject.video.video_platform.repository.products.download.DownloadProductRepository;
import com.myproject.video.video_platform.repository.products.download.FileDownloadProductRepository;
import com.myproject.video.video_platform.repository.products.download.SectionDownloadProductRepository;
import com.myproject.video.video_platform.service.digitalocean.SpacesS3Service;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.stereotype.Service;

import java.time.Duration;
import java.time.LocalDateTime;
import java.util.UUID;

@Service
@Slf4j
@RequiredArgsConstructor
public class FilesService {

    @Value("${digitalocean.spaces.cdnEndpointUrl}")
    private String cdnEndpointUrl;

    @Value("${digitalocean.spaces.bucket-media}")
    private String s3mediaBucket;

    private final SpacesS3Service spacesS3Service;
    private final SectionDownloadProductRepository sectionRepository;
    private final DownloadProductRepository downloadProductRepository;
    private final FileDownloadProductRepository fileRepository;
    private final ProductRepository productRepository;
    private final ProductAuthorizationService productAuthorizationService;


    /**
     * Build key, check ownership, sign URL, return all info.
     */
    public PresignedUrlResponseDto generateLegacyPresignedUrl(
            String sectionIdStr,
            String folderTypeStr,
            String filename,
            Duration expiration
    ) {
        SectionDownloadProduct section = authorizeSectionUpload(sectionIdStr);
        S3UploadFolder folder  = S3UploadFolder.fromString(folderTypeStr);
        UUID fileId = UUID.randomUUID();

        String key = buildKey(section, folder, filename, fileId);
        String presigned = spacesS3Service.generatePresignedUrlForPut(key, expiration);
        String fileUrl   = cdnEndpointUrl + "/" + s3mediaBucket + "/" + key;

        PresignedUrlResponseDto dto = new PresignedUrlResponseDto();
        dto.setFileId(fileId.toString());
        dto.setPresignedUrl(presigned);
        dto.setKey(key);
        dto.setFileUrl(fileUrl);
        return dto;
    }

    public PresignedUrlResponseDto generatePresignedUrl(
            String productIdStr,
            String sectionIdStr,
            String filename,
            Duration expiration
    ) {
        SectionDownloadProduct section = authorizeSectionUpload(productIdStr, sectionIdStr);
        UUID fileId = UUID.randomUUID();

        String key = buildKey(section, S3UploadFolder.DOWNLOAD_SECTION_FILES, filename, fileId);
        String presigned = spacesS3Service.generatePresignedUrlForPut(key, expiration);
        String fileUrl = cdnEndpointUrl + "/" + s3mediaBucket + "/" + key;

        PresignedUrlResponseDto dto = new PresignedUrlResponseDto();
        dto.setFileId(fileId.toString());
        dto.setPresignedUrl(presigned);
        dto.setKey(key);
        dto.setFileUrl(fileUrl);
        return dto;
    }

    /** throws if the current user isn’t owner of that section */
    private SectionDownloadProduct authorizeSectionUpload(String sectionIdStr) {
        UUID sectionId = UUID.fromString(sectionIdStr);

        SectionDownloadProduct section = sectionRepository.findById(sectionId)
                .orElseThrow(() -> new ResourceNotFoundException("Section not found: " + sectionId));

        productAuthorizationService.requireOwnerOrAdmin(section.getDownloadProduct());
        return section;
    }

    private SectionDownloadProduct authorizeSectionUpload(String productIdStr, String sectionIdStr) {
        Product product = productRepository.findById(UUID.fromString(productIdStr))
                .orElseThrow(() -> new ResourceNotFoundException("Product not found: " + productIdStr));

        if (product.getType() != ProductType.DOWNLOAD) {
            throw new UnsupportedProductOperationException("File uploads are only supported for DOWNLOAD products.");
        }

        productAuthorizationService.requireOwnerOrAdmin(product);

        SectionDownloadProduct section = sectionRepository.findById(UUID.fromString(sectionIdStr))
                .orElseThrow(() -> new ResourceNotFoundException("Section not found: " + sectionIdStr));

        if (!section.getDownloadProduct().getId().equals(product.getId())) {
            throw new ResourceNotFoundException(
                    "Section not found for download product " + productIdStr + ": " + sectionIdStr
            );
        }

        return section;
    }

    /** place to construct S3 path for ANY upload type */
    private String buildKey(SectionDownloadProduct section,
                            S3UploadFolder folder,
                            String filename, UUID fileId) {

        String userId     = section.getDownloadProduct().getUser().getUserId().toString();
        String sectionId  = section.getId().toString();
        String safeName   = filename.replaceAll("\\s+", "_");
        return String.join("/",
                "users-content",
                userId,
                folder.getFolderName(),
                sectionId,
                fileId + "_" + safeName
        );
    }

    public FileS3UploadResponseDto confirmUpload(ConfirmUploadRequestDto dto) {
        SectionDownloadProduct section = authorizeSectionUpload(dto.getSectionId());

        FileDownloadProduct fileEntity = new FileDownloadProduct();
        fileEntity.setFileName(dto.getFileName());
        fileEntity.setUserId(section.getDownloadProduct().getUser().getUserId());
        fileEntity.setSection(section);
        fileEntity.setSize(dto.getFileSize());
        fileEntity.setPath(dto.getKey());
        fileEntity.setFileType(dto.getFileType());
        fileEntity.setUploadedAt(LocalDateTime.now());
        fileEntity.setDownloadCount(0);
        fileEntity = fileRepository.save(fileEntity);
        section.getDownloadProduct().setUpdatedAt(LocalDateTime.now());
        downloadProductRepository.save(section.getDownloadProduct());

        FileS3UploadResponseDto resp = new FileS3UploadResponseDto();
        resp.setFileId  (fileEntity.getId().toString());
        resp.setFileName(fileEntity.getFileName());

        resp.setUrl(dto.getFileUrl() != null
                ? dto.getFileUrl()
                : cdnEndpointUrl + "/" + s3mediaBucket + "/" + dto.getKey());
        return resp;
    }

    public FileS3UploadResponseDto confirmUpload(
            String productIdStr,
            String sectionIdStr,
            ConfirmUploadRequestDto dto
    ) {
        SectionDownloadProduct section = authorizeSectionUpload(productIdStr, sectionIdStr);

        FileDownloadProduct fileEntity = new FileDownloadProduct();
        fileEntity.setFileName(dto.getFileName());
        fileEntity.setUserId(section.getDownloadProduct().getUser().getUserId());
        fileEntity.setSection(section);
        fileEntity.setSize(dto.getFileSize());
        fileEntity.setPath(dto.getKey());
        fileEntity.setFileType(dto.getFileType());
        fileEntity.setUploadedAt(LocalDateTime.now());
        fileEntity.setDownloadCount(0);
        fileEntity = fileRepository.save(fileEntity);

        section.getDownloadProduct().setUpdatedAt(LocalDateTime.now());
        downloadProductRepository.save(section.getDownloadProduct());

        FileS3UploadResponseDto resp = new FileS3UploadResponseDto();
        resp.setFileId(fileEntity.getId().toString());
        resp.setFileName(fileEntity.getFileName());
        resp.setUrl(dto.getFileUrl() != null
                ? dto.getFileUrl()
                : cdnEndpointUrl + "/" + s3mediaBucket + "/" + dto.getKey());
        return resp;
    }

    public void deleteFile(String productIdStr, String sectionIdStr, String fileIdStr) {
        SectionDownloadProduct section = authorizeSectionUpload(productIdStr, sectionIdStr);

        FileDownloadProduct file = fileRepository.findById(UUID.fromString(fileIdStr))
                .orElseThrow(() -> new ResourceNotFoundException("File not found: " + fileIdStr));

        if (!file.getSection().getId().equals(section.getId())) {
            throw new ResourceNotFoundException(
                    "File not found for section " + sectionIdStr + ": " + fileIdStr
            );
        }

        fileRepository.delete(file);
        section.getDownloadProduct().setUpdatedAt(LocalDateTime.now());
        downloadProductRepository.save(section.getDownloadProduct());
    }
}

package com.myproject.video.video_platform.service.product.membership;

import com.fasterxml.jackson.databind.JsonNode;
import com.myproject.video.video_platform.common.enums.membership.MembershipContentStatus;
import com.myproject.video.video_platform.common.enums.membership.MembershipContentType;
import com.myproject.video.video_platform.common.enums.membership.MembershipFeedEntryKind;
import com.myproject.video.video_platform.common.enums.membership.MembershipOrderingMode;
import com.myproject.video.video_platform.common.enums.products.ProductType;
import com.myproject.video.video_platform.dto.products.membership.MembershipDtos;
import com.myproject.video.video_platform.entity.products.Product;
import com.myproject.video.video_platform.entity.products.membership.MembershipContent;
import com.myproject.video.video_platform.entity.products.membership.MembershipFeedEntry;
import com.myproject.video.video_platform.entity.products.membership.MembershipProduct;
import com.myproject.video.video_platform.exception.product.ResourceNotFoundException;
import com.myproject.video.video_platform.exception.product.UnsupportedProductOperationException;
import com.myproject.video.video_platform.repository.products.ProductRepository;
import com.myproject.video.video_platform.repository.products.membership.MembershipContentRepository;
import com.myproject.video.video_platform.repository.products.membership.MembershipFeedEntryRepository;
import com.myproject.video.video_platform.repository.products.membership.MembershipProductRepository;
import com.myproject.video.video_platform.service.product.ProductAuthorizationService;
import lombok.RequiredArgsConstructor;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import java.time.Instant;
import java.time.LocalDateTime;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.HashMap;
import java.util.HashSet;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.UUID;

@Service
@RequiredArgsConstructor
public class MembershipService {
    private static final long MAX_ASSET_SIZE = 500L * 1024L * 1024L;

    private final ProductRepository productRepository;
    private final MembershipProductRepository membershipRepository;
    private final MembershipContentRepository contentRepository;
    private final MembershipFeedEntryRepository feedRepository;
    private final ProductAuthorizationService authorizationService;

    @Transactional(readOnly = true)
    public MembershipDtos.Aggregate getAggregate(UUID productId) {
        MembershipProduct membership = requireMembership(productId);
        authorizationService.requireOwnerOrAdmin(membership);
        return aggregate(membership);
    }

    @Transactional
    public MembershipDtos.Aggregate updateConfig(UUID productId, JsonNode request) {
        MembershipProduct membership = requireOwnedMembership(productId);
        if (request != null && request.hasNonNull("orderingMode")) {
            MembershipOrderingMode next = enumValue(
                    MembershipOrderingMode.class,
                    request.get("orderingMode").asText(),
                    "orderingMode"
            );
            if (next != membership.getOrderingMode()) {
                membership.setOrderingMode(next);
                normalizeStoredOrdering(membership, feedRepository.findAllByMembershipId(productId));
            }
        }
        touch(membership);
        return aggregate(membership);
    }

    @Transactional
    public MembershipDtos.Content createContent(UUID productId, JsonNode request) {
        MembershipProduct membership = requireOwnedMembership(productId);
        if (request == null || !request.isObject()) {
            throw new IllegalArgumentException("Membership content payload is required");
        }

        MembershipContent content = new MembershipContent();
        content.setMembership(membership);
        content.setType(enumValue(MembershipContentType.class, requiredText(request, "type"), "type"));
        content.setTitle(requiredText(request, "title"));
        content.setDescription(optionalText(request, "description"));
        content.setStatus(enumValue(MembershipContentStatus.class, requiredText(request, "status"), "status"));
        applyTypePayload(content, request, true);
        validateContent(content);
        content = contentRepository.saveAndFlush(content);

        List<MembershipFeedEntry> entries = feedRepository.findAllByMembershipId(productId);
        if (membership.getOrderingMode() == MembershipOrderingMode.MANUAL) {
            entries.forEach(entry -> entry.setPosition(entry.getPosition() == null ? 2 : entry.getPosition() + 1));
            feedRepository.saveAll(entries);
        }
        MembershipFeedEntry entry = new MembershipFeedEntry();
        entry.setMembership(membership);
        entry.setKind(MembershipFeedEntryKind.CONTENT);
        entry.setContent(content);
        entry.setAddedAt(Instant.now());
        entry.setPosition(membership.getOrderingMode() == MembershipOrderingMode.MANUAL ? 1 : null);
        feedRepository.save(entry);
        touch(membership);
        return mapContent(content, entry.getPosition());
    }

    @Transactional
    public MembershipDtos.Content updateContent(UUID productId, UUID contentId, JsonNode request) {
        MembershipProduct membership = requireOwnedMembership(productId);
        MembershipContent content = contentRepository.findByIdAndMembershipId(contentId, productId)
                .orElseThrow(() -> new ResourceNotFoundException("Membership content not found: " + contentId));
        if (request == null || !request.isObject()) {
            throw new IllegalArgumentException("Membership content payload is required");
        }
        if (request.hasNonNull("type")) {
            MembershipContentType requestedType = enumValue(
                    MembershipContentType.class, request.get("type").asText(), "type");
            if (requestedType != content.getType()) {
                throw conflict("Membership content type cannot be changed");
            }
        }
        if (request.has("title")) {
            content.setTitle(requiredText(request, "title"));
        }
        if (request.has("description")) {
            content.setDescription(optionalText(request, "description"));
        }
        if (request.hasNonNull("status")) {
            content.setStatus(enumValue(
                    MembershipContentStatus.class, request.get("status").asText(), "status"));
        }
        applyTypePayload(content, request, false);
        validateContent(content);
        content = contentRepository.saveAndFlush(content);
        touch(membership);
        MembershipFeedEntry contentEntry = feedRepository.findAllByMembershipId(productId).stream()
                .filter(entry -> entry.getContent() != null && entry.getContent().getId().equals(contentId))
                .findFirst()
                .orElse(null);
        Integer position = contentEntry == null ? null : contentEntry.getPosition();
        return mapContent(content, position);
    }

    @Transactional
    public void deleteContent(UUID productId, UUID contentId) {
        MembershipProduct membership = requireOwnedMembership(productId);
        MembershipContent content = contentRepository.findByIdAndMembershipId(contentId, productId)
                .orElseThrow(() -> new ResourceNotFoundException("Membership content not found: " + contentId));
        feedRepository.deleteByMembershipIdAndContentId(productId, contentId);
        contentRepository.delete(content);
        contentRepository.flush();
        normalizeStoredOrdering(membership, feedRepository.findAllByMembershipId(productId));
        touch(membership);
    }

    @Transactional
    public MembershipDtos.Aggregate replaceFeed(UUID productId, JsonNode request) {
        MembershipProduct membership = requireOwnedMembership(productId);
        if (request == null || !request.isObject() || !request.has("feed") || !request.get("feed").isArray()) {
            throw new IllegalArgumentException("Membership feed array is required");
        }
        MembershipOrderingMode orderingMode = enumValue(
                MembershipOrderingMode.class, requiredText(request, "orderingMode"), "orderingMode");
        List<MembershipContent> content = contentRepository.findAllByMembershipId(productId);
        Map<UUID, MembershipContent> contentById = new HashMap<>();
        content.forEach(item -> contentById.put(item.getId(), item));

        Map<String, MembershipFeedEntry> existing = new HashMap<>();
        for (MembershipFeedEntry entry : feedRepository.findAllByMembershipId(productId)) {
            existing.put(identity(entry), entry);
        }

        List<MembershipFeedEntry> replacement = new ArrayList<>();
        Set<String> identities = new HashSet<>();
        Set<UUID> referencedContentIds = new HashSet<>();
        int requestPosition = 1;
        for (JsonNode node : request.get("feed")) {
            MembershipFeedEntryKind kind = enumValue(
                    MembershipFeedEntryKind.class, requiredText(node, "kind"), "feed.kind");
            MembershipFeedEntry entry;
            String identity;
            if (kind == MembershipFeedEntryKind.CONTENT) {
                UUID contentId = requiredUuid(node, "contentId");
                MembershipContent target = contentById.get(contentId);
                if (target == null) {
                    throw conflict("Feed content must belong to this Membership: " + contentId);
                }
                identity = "content:" + contentId;
                entry = existing.getOrDefault(identity, new MembershipFeedEntry());
                entry.setContent(target);
                entry.setIncludedProductId(null);
                referencedContentIds.add(contentId);
            } else {
                UUID includedProductId = requiredUuid(node, "productId");
                validateIncludedProduct(membership, includedProductId);
                identity = "product:" + includedProductId;
                entry = existing.getOrDefault(identity, new MembershipFeedEntry());
                entry.setContent(null);
                entry.setIncludedProductId(includedProductId);
            }
            if (!identities.add(identity)) {
                throw conflict("Duplicate Membership feed entry: " + identity);
            }
            entry.setMembership(membership);
            entry.setKind(kind);
            if (entry.getAddedAt() == null) {
                entry.setAddedAt(Instant.now());
            }
            entry.setPosition(orderingMode == MembershipOrderingMode.MANUAL ? requestPosition : null);
            replacement.add(entry);
            requestPosition++;
        }
        if (!referencedContentIds.equals(contentById.keySet())) {
            throw conflict("The feed must contain every native Membership content item exactly once");
        }

        List<MembershipFeedEntry> removed = existing.entrySet().stream()
                .filter(entry -> !identities.contains(entry.getKey()))
                .map(Map.Entry::getValue)
                .toList();
        feedRepository.deleteAll(removed);
        feedRepository.saveAll(replacement);
        membership.setOrderingMode(orderingMode);
        touch(membership);
        return aggregate(membership);
    }

    private MembershipProduct requireOwnedMembership(UUID productId) {
        MembershipProduct membership = requireMembership(productId);
        authorizationService.requireOwnerOrAdmin(membership);
        return membership;
    }

    private MembershipProduct requireMembership(UUID productId) {
        Product product = productRepository.findById(productId)
                .orElseThrow(() -> new ResourceNotFoundException("Product not found: " + productId));
        if (!(product instanceof MembershipProduct membership)) {
            throw conflict("Product is not a Membership: " + productId);
        }
        return membership;
    }

    private void validateIncludedProduct(MembershipProduct membership, UUID productId) {
        Product product = productRepository.findById(productId)
                .orElseThrow(() -> conflict("Included Product does not exist: " + productId));
        if (!product.getUser().getUserId().equals(membership.getUser().getUserId())) {
            throw conflict("Included Products must belong to the Membership owner");
        }
        if (product.getType() != ProductType.COURSE && product.getType() != ProductType.DOWNLOAD) {
            throw conflict("Only Course and Download Products can be included in a Membership");
        }
    }

    private MembershipDtos.Aggregate aggregate(MembershipProduct membership) {
        List<MembershipFeedEntry> entries = feedRepository.findAllByMembershipId(membership.getId());
        sort(entries, membership.getOrderingMode());
        Map<UUID, Integer> positions = new LinkedHashMap<>();
        entries.stream()
                .filter(entry -> entry.getContent() != null)
                .forEach(entry -> positions.put(entry.getContent().getId(), entry.getPosition()));
        Map<UUID, MembershipContent> contentById = new HashMap<>();
        contentRepository.findAllByMembershipId(membership.getId())
                .forEach(item -> contentById.put(item.getId(), item));
        List<MembershipDtos.Content> content = entries.stream()
                .filter(entry -> entry.getContent() != null)
                .map(entry -> contentById.get(entry.getContent().getId()))
                .filter(java.util.Objects::nonNull)
                .map(item -> mapContent(item, positions.get(item.getId())))
                .toList();
        List<MembershipDtos.FeedEntry> feed = entries.stream().map(this::mapFeedEntry).toList();
        LocalDateTime updatedAt = membership.getUpdatedAt() == null
                ? membership.getCreatedAt() : membership.getUpdatedAt();
        return new MembershipDtos.Aggregate(
                membership.getId(),
                new MembershipDtos.Config(membership.getId(), membership.getOrderingMode().name()),
                content,
                feed,
                updatedAt
        );
    }

    private void normalizeStoredOrdering(MembershipProduct membership, List<MembershipFeedEntry> entries) {
        sort(entries, membership.getOrderingMode());
        for (int index = 0; index < entries.size(); index++) {
            entries.get(index).setPosition(
                    membership.getOrderingMode() == MembershipOrderingMode.MANUAL ? index + 1 : null);
        }
        feedRepository.saveAll(entries);
    }

    private void sort(List<MembershipFeedEntry> entries, MembershipOrderingMode mode) {
        if (mode == MembershipOrderingMode.MANUAL) {
            entries.sort(Comparator.comparing(
                    MembershipFeedEntry::getPosition,
                    Comparator.nullsLast(Integer::compareTo)
            ));
        } else {
            entries.sort(Comparator.comparing(
                    MembershipFeedEntry::getAddedAt,
                    Comparator.nullsLast(Comparator.reverseOrder())
            ));
        }
    }

    private void applyTypePayload(MembershipContent content, JsonNode request, boolean creating) {
        if (content.getType() == MembershipContentType.POST) {
            if (creating || request.has("body")) {
                content.setBody(requiredText(request, "body"));
            }
            content.setAssetFileId(null);
            content.setAssetFileName(null);
            content.setAssetFileType(null);
            content.setAssetSize(null);
            return;
        }
        String field = content.getType() == MembershipContentType.VIDEO ? "video" : "file";
        if (creating || request.has(field)) {
            JsonNode asset = request.get(field);
            if (asset == null || !asset.isObject()) {
                throw new IllegalArgumentException(field + " metadata is required");
            }
            String fileName = requiredText(asset, "fileName");
            String fileType = requiredText(asset, "fileType");
            long size = requiredLong(asset, "size");
            boolean unchanged = content.getAssetFileId() != null
                    && content.getAssetFileName() != null
                    && content.getAssetFileName().equals(fileName)
                    && content.getAssetFileType().equals(fileType)
                    && content.getAssetSize() != null
                    && content.getAssetSize() == size
                    && asset.hasNonNull("fileId")
                    && content.getAssetFileId().toString().equals(asset.get("fileId").asText());
            content.setAssetFileId(unchanged ? content.getAssetFileId() : UUID.randomUUID());
            content.setAssetFileName(fileName);
            content.setAssetFileType(fileType);
            content.setAssetSize(size);
        }
        content.setBody(null);
    }

    private void validateContent(MembershipContent content) {
        if (content.getTitle() == null || content.getTitle().isBlank() || content.getTitle().trim().length() > 255) {
            throw new IllegalArgumentException("Content title is required and must not exceed 255 characters");
        }
        content.setTitle(content.getTitle().trim());
        if (content.getType() == MembershipContentType.POST) {
            if (content.getBody() == null || content.getBody().isBlank()) {
                throw new IllegalArgumentException("Post body is required");
            }
        } else if (content.getAssetFileId() == null
                || content.getAssetFileName() == null || content.getAssetFileName().isBlank()
                || content.getAssetFileName().length() > 255
                || content.getAssetFileType() == null || content.getAssetFileType().isBlank()
                || content.getAssetFileType().length() > 150
                || content.getAssetSize() == null || content.getAssetSize() <= 0
                || content.getAssetSize() > MAX_ASSET_SIZE) {
            throw new IllegalArgumentException("Asset metadata is invalid or exceeds the 500 MiB limit");
        }
    }

    private MembershipDtos.Content mapContent(MembershipContent content, Integer position) {
        MembershipDtos.AssetRef asset = content.getType() == MembershipContentType.POST ? null
                : new MembershipDtos.AssetRef(
                        content.getAssetFileId(), content.getAssetFileName(),
                        content.getAssetFileType(), content.getAssetSize());
        return new MembershipDtos.Content(
                content.getId(), content.getType().name(), content.getTitle(), content.getDescription(),
                content.getStatus().name(), content.getBody(),
                content.getType() == MembershipContentType.VIDEO ? asset : null,
                content.getType() == MembershipContentType.RESOURCE ? asset : null,
                content.getCreatedAt(), content.getUpdatedAt(), position
        );
    }

    private MembershipDtos.FeedEntry mapFeedEntry(MembershipFeedEntry entry) {
        UUID contentId = entry.getContent() == null ? null : entry.getContent().getId();
        UUID productId = entry.getIncludedProductId();
        return new MembershipDtos.FeedEntry(
                entry.getKind() == MembershipFeedEntryKind.CONTENT
                        ? "content:" + contentId : "product:" + productId,
                entry.getKind().name(), contentId, productId, entry.getAddedAt(), entry.getPosition()
        );
    }

    private String identity(MembershipFeedEntry entry) {
        return entry.getKind() == MembershipFeedEntryKind.CONTENT
                ? "content:" + entry.getContent().getId()
                : "product:" + entry.getIncludedProductId();
    }

    private void touch(MembershipProduct membership) {
        membership.setUpdatedAt(LocalDateTime.now());
        membershipRepository.save(membership);
    }

    private static String requiredText(JsonNode node, String field) {
        if (node == null || !node.hasNonNull(field) || !node.get(field).isTextual()
                || node.get(field).asText().isBlank()) {
            throw new IllegalArgumentException(field + " is required");
        }
        return node.get(field).asText().trim();
    }

    private static String optionalText(JsonNode node, String field) {
        if (!node.has(field) || node.get(field).isNull()) {
            return null;
        }
        if (!node.get(field).isTextual()) {
            throw new IllegalArgumentException(field + " must be text");
        }
        return node.get(field).asText();
    }

    private static long requiredLong(JsonNode node, String field) {
        if (!node.hasNonNull(field) || !node.get(field).isIntegralNumber()
                || !node.get(field).canConvertToLong()) {
            throw new IllegalArgumentException(field + " is required and must be an integer");
        }
        return node.get(field).asLong();
    }

    private static UUID requiredUuid(JsonNode node, String field) {
        try {
            return UUID.fromString(requiredText(node, field));
        } catch (IllegalArgumentException exception) {
            throw new IllegalArgumentException(field + " must be a UUID");
        }
    }

    private static <T extends Enum<T>> T enumValue(Class<T> type, String value, String field) {
        try {
            return Enum.valueOf(type, value.trim().toUpperCase());
        } catch (IllegalArgumentException exception) {
            throw new IllegalArgumentException("Invalid " + field + ": " + value);
        }
    }

    private static UnsupportedProductOperationException conflict(String message) {
        return new UnsupportedProductOperationException(message);
    }
}

package com.myproject.video.video_platform.service.product.strategy_handler;

import com.myproject.video.video_platform.common.converter.product.MembershipProductConverter;
import com.myproject.video.video_platform.common.enums.products.ProductType;
import com.myproject.video.video_platform.dto.products.AbstractProductRequestDto;
import com.myproject.video.video_platform.dto.products.AbstractProductResponseDto;
import com.myproject.video.video_platform.dto.products.membership.MembershipProductRequestDto;
import com.myproject.video.video_platform.entity.products.membership.MembershipProduct;
import com.myproject.video.video_platform.entity.user.User;
import com.myproject.video.video_platform.exception.product.ResourceNotFoundException;
import com.myproject.video.video_platform.repository.products.membership.MembershipProductRepository;
import com.myproject.video.video_platform.repository.products.membership.MembershipContentRepository;
import com.myproject.video.video_platform.repository.products.membership.MembershipFeedEntryRepository;
import com.myproject.video.video_platform.service.product.ProductAuthorizationService;
import com.myproject.video.video_platform.service.product.ProductPublicationValidator;
import lombok.RequiredArgsConstructor;
import org.springframework.stereotype.Component;
import org.springframework.transaction.annotation.Transactional;

import java.util.UUID;

@Component
@RequiredArgsConstructor
public class MembershipProductHandler implements ProductTypeHandler {
    private final MembershipProductRepository repository;
    private final MembershipProductConverter converter;
    private final ProductAuthorizationService authorizationService;
    private final MembershipContentRepository contentRepository;
    private final MembershipFeedEntryRepository feedRepository;
    private final ProductPublicationValidator publicationValidator;

    @Override
    public ProductType getSupportedType() {
        return ProductType.MEMBERSHIP;
    }

    @Override
    @Transactional
    public AbstractProductResponseDto createProduct(AbstractProductRequestDto baseDto) {
        MembershipProductRequestDto dto = (MembershipProductRequestDto) baseDto;
        User owner = authorizationService.resolveOwnerForCreate(dto);
        MembershipProduct product = converter.fromCreate(dto, owner);
        publicationValidator.validate(product);
        return converter.toResponse(repository.saveAndFlush(product));
    }

    @Override
    @Transactional(readOnly = true)
    public AbstractProductResponseDto getProductById(String productId) {
        MembershipProduct product = find(productId);
        return converter.toResponse(product);
    }

    @Override
    @Transactional
    public AbstractProductResponseDto updateProduct(AbstractProductRequestDto baseDto) {
        MembershipProductRequestDto dto = (MembershipProductRequestDto) baseDto;
        MembershipProduct product = find(dto.getId());
        authorizationService.requireOwnerOrAdmin(product);
        converter.applyUpdate(product, dto);
        publicationValidator.validate(product);
        return converter.toResponse(repository.save(product));
    }

    @Override
    @Transactional
    public void deleteProduct(String userId, String productId) {
        MembershipProduct product = find(productId);
        authorizationService.requireOwnerOrAdmin(product);
        feedRepository.deleteAllByMembershipId(product.getId());
        contentRepository.deleteAllByMembershipId(product.getId());
        repository.delete(product);
    }

    private MembershipProduct find(String productId) {
        return repository.findById(UUID.fromString(productId))
                .orElseThrow(() -> new ResourceNotFoundException("Membership not found: " + productId));
    }
}

package com.myproject.video.video_platform.service.creator;

import com.myproject.video.video_platform.common.enums.commerce.CommerceOrderStatus;
import com.myproject.video.video_platform.dto.creator.CreatorPageResponse;
import com.myproject.video.video_platform.dto.creator.sales.CreatorSalesDtos;
import com.myproject.video.video_platform.entity.commerce.CommerceOrder;
import com.myproject.video.video_platform.entity.commerce.CommerceOrderItem;
import com.myproject.video.video_platform.entity.commerce.CommercePaymentAttempt;
import com.myproject.video.video_platform.entity.entitlement.ProductEntitlement;
import com.myproject.video.video_platform.entity.products.Product;
import com.myproject.video.video_platform.exception.product.ResourceNotFoundException;
import com.myproject.video.video_platform.repository.creator.CreatorReportingQueryRepository;
import com.myproject.video.video_platform.service.user.CurrentUserService;
import lombok.RequiredArgsConstructor;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import java.time.Clock;
import java.time.Instant;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Set;
import java.util.UUID;

@Service
@RequiredArgsConstructor
public class CreatorSalesService {
    private final CurrentUserService currentUserService;
    private final CreatorReportingQueryRepository reportingRepository;
    private final Clock reportingClock;

    @Transactional(readOnly = true)
    public CreatorSalesDtos.Summary summary(String periodValue) {
        ReportingEnums.Period period = ReportingEnums.Period.sales(periodValue);
        ReportingWindow window = ReportingWindow.forPeriod(period, reportingClock);
        var data = reportingRepository.load(currentUserService.getCurrentUserId());
        long currentRevenue = sum(data.orders(), CommerceOrderStatus.PAID, window, Event.PAID);
        long previousRevenue = sumPrevious(data.orders(), CommerceOrderStatus.PAID, window, Event.PAID);
        long currentOrders = count(data.orders(), CommerceOrderStatus.PAID, window, Event.PAID, false);
        long previousOrders = count(data.orders(), CommerceOrderStatus.PAID, window, Event.PAID, true);
        long currentRefunds = sum(data.orders(), CommerceOrderStatus.REFUNDED, window, Event.REFUNDED);
        long previousRefunds = sumPrevious(data.orders(), CommerceOrderStatus.REFUNDED, window, Event.REFUNDED);
        long currentFailures = count(data.orders(), CommerceOrderStatus.FAILED, window, Event.FAILED, false);
        long previousFailures = count(data.orders(), CommerceOrderStatus.FAILED, window, Event.FAILED, true);
        String currency = data.orders().stream().map(CommerceOrder::getCurrency).findFirst().orElse("EUR");
        return new CreatorSalesDtos.Summary(period.wireValue(), List.of(
                metric("Revenue", CreatorReportingSupport.money(currentRevenue, currency), currentRevenue, previousRevenue, false),
                metric("Orders", Long.toString(currentOrders), currentOrders, previousOrders, false),
                metric("Refunds", CreatorReportingSupport.money(currentRefunds, currency), currentRefunds, previousRefunds, true),
                metric("Failed payments", Long.toString(currentFailures), currentFailures, previousFailures, true)
        ));
    }

    @Transactional(readOnly = true)
    public CreatorSalesDtos.OrdersPage orders(
            int page, int pageSize, String search, String statusValue, String productValue,
            String periodValue, String sortValue
    ) {
        validatePage(page, pageSize);
        ReportingEnums.Period period = ReportingEnums.Period.sales(periodValue);
        ReportingEnums.SalesStatus status = ReportingEnums.SalesStatus.parse(statusValue);
        ReportingEnums.SalesSort sort = ReportingEnums.SalesSort.parse(sortValue);
        UUID productId = productValue == null || productValue.isBlank() ? null : parseUuid(productValue, "product");
        ReportingWindow window = ReportingWindow.forPeriod(period, reportingClock);
        Instant now = reportingClock.instant();
        var data = reportingRepository.load(currentUserService.getCurrentUserId());
        Set<UUID> qualifyingCustomers = CreatorReportingSupport.qualifyingCustomerIds(data.orders(), data.entitlements());
        Map<UUID, Product> products = CreatorReportingSupport.productsById(data.products());
        Map<UUID, ProductEntitlement> access = CreatorReportingSupport.purchaseEntitlementsByItem(data.entitlements());
        String normalizedSearch = search == null ? "" : search.trim().toLowerCase(Locale.ROOT);

        List<CommerceOrder> filtered = data.orders().stream()
                .filter(order -> visible(order, now))
                .filter(order -> window.current(order.getCreatedAt()))
                .filter(order -> status == ReportingEnums.SalesStatus.ALL || order.getStatus() == status.status())
                .filter(order -> productId == null || order.getItems().stream().anyMatch(item -> item.getProductId().equals(productId)))
                .filter(order -> matches(order, normalizedSearch))
                .sorted(orderComparator(sort))
                .toList();
        List<CreatorSalesDtos.OrderListItem> mapped = filtered.stream()
                .map(order -> listItem(order, qualifyingCustomers, products, access)).toList();
        CreatorPageResponse<CreatorSalesDtos.OrderListItem> result = CreatorPageResponse.of(mapped, page, pageSize);
        return new CreatorSalesDtos.OrdersPage(result.content(), result.totalElements(), result.totalPages(),
                result.size(), result.number(), result.first(), result.last(), result.empty(),
                CreatorReportingSupport.productOptions(data.products(), data.orders()));
    }

    @Transactional(readOnly = true)
    public CreatorSalesDtos.OrderDetail order(UUID orderId) {
        var data = reportingRepository.load(currentUserService.getCurrentUserId());
        CommerceOrder order = data.orders().stream().filter(candidate -> candidate.getId().equals(orderId))
                .filter(candidate -> visible(candidate, reportingClock.instant()))
                .findFirst().orElseThrow(() -> new ResourceNotFoundException("Order not found"));
        Set<UUID> qualifyingCustomers = CreatorReportingSupport.qualifyingCustomerIds(data.orders(), data.entitlements());
        Map<UUID, Product> products = CreatorReportingSupport.productsById(data.products());
        Map<UUID, ProductEntitlement> access = CreatorReportingSupport.purchaseEntitlementsByItem(data.entitlements());
        List<CreatorSalesDtos.Item> items = items(order, products, access);
        CommercePaymentAttempt attempt = data.attemptsByOrderId().get(order.getId());
        List<CreatorSalesDtos.SummaryRow> rows = new ArrayList<>();
        order.getItems().forEach(item -> rows.add(new CreatorSalesDtos.SummaryRow(item.getProductName(), item.getLineTotalMinor())));
        rows.add(new CreatorSalesDtos.SummaryRow("Total", order.getTotalMinor()));
        return new CreatorSalesDtos.OrderDetail(
                order.getId().toString(), order.getCreatedAt(), wireStatus(order), "one-time", order.getTotalMinor(),
                order.getCurrency(), customer(order, qualifyingCustomers), singleProduct(items), items,
                attempt == null ? null : title(attempt.getProvider().name()), null,
                attempt == null ? null : attempt.getProviderPaymentId(), order.getPaidAt(), rows,
                singleAccess(items), order.getStatus() == CommerceOrderStatus.REFUNDED
                        ? new CreatorSalesDtos.Refund(order.getTotalMinor(), order.getRefundedAt(), null) : null,
                order.getStatus() == CommerceOrderStatus.FAILED
                        ? new CreatorSalesDtos.Failure(attempt == null || attempt.getFailureMessage() == null
                        ? "Payment failed." : attempt.getFailureMessage(), null) : null
        );
    }

    private CreatorSalesDtos.OrderListItem listItem(
            CommerceOrder order, Set<UUID> qualifyingCustomers, Map<UUID, Product> products,
            Map<UUID, ProductEntitlement> access
    ) {
        List<CreatorSalesDtos.Item> items = items(order, products, access);
        return new CreatorSalesDtos.OrderListItem(order.getId().toString(), order.getCreatedAt(), wireStatus(order),
                "one-time", order.getTotalMinor(), order.getCurrency(), customer(order, qualifyingCustomers),
                singleProduct(items), items);
    }

    private List<CreatorSalesDtos.Item> items(
            CommerceOrder order, Map<UUID, Product> products, Map<UUID, ProductEntitlement> access
    ) {
        return order.getItems().stream().map(item -> new CreatorSalesDtos.Item(
                CreatorReportingSupport.salesProduct(item, products), item.getLineTotalMinor(),
                CreatorReportingSupport.access(access.get(item.getId())))).toList();
    }

    private CreatorSalesDtos.Customer customer(CommerceOrder order, Set<UUID> qualifying) {
        var buyer = order.getBuyer();
        return new CreatorSalesDtos.Customer(qualifying.contains(buyer.getUserId()) ? buyer.getUserId().toString() : null,
                CreatorReportingSupport.name(buyer), buyer.getEmail());
    }

    private static CreatorSalesDtos.Product singleProduct(List<CreatorSalesDtos.Item> items) {
        return items.size() == 1 ? items.get(0).product() : null;
    }

    private static CreatorSalesDtos.Access singleAccess(List<CreatorSalesDtos.Item> items) {
        return items.size() == 1 ? items.get(0).access() : null;
    }

    private static boolean visible(CommerceOrder order, Instant now) {
        if (order.getStatus() == CommerceOrderStatus.EXPIRED) return false;
        return order.getStatus() != CommerceOrderStatus.PENDING || order.getExpiresAt().isAfter(now);
    }

    private static boolean matches(CommerceOrder order, String search) {
        if (search.isBlank()) return true;
        String customer = (CreatorReportingSupport.name(order.getBuyer()) + " " + order.getBuyer().getEmail())
                .toLowerCase(Locale.ROOT);
        return order.getId().toString().toLowerCase(Locale.ROOT).contains(search) || customer.contains(search);
    }

    private static Comparator<CommerceOrder> orderComparator(ReportingEnums.SalesSort sort) {
        Comparator<CommerceOrder> comparator = switch (sort) {
            case NEWEST -> Comparator.comparing(CommerceOrder::getCreatedAt).reversed();
            case OLDEST -> Comparator.comparing(CommerceOrder::getCreatedAt);
            case AMOUNT_DESC -> Comparator.comparingLong(CommerceOrder::getTotalMinor).reversed();
            case AMOUNT_ASC -> Comparator.comparingLong(CommerceOrder::getTotalMinor);
        };
        return comparator.thenComparing(CommerceOrder::getId);
    }

    private static String wireStatus(CommerceOrder order) {
        return order.getStatus().name().toLowerCase(Locale.ROOT);
    }

    private static String title(String value) {
        return value.substring(0, 1) + value.substring(1).toLowerCase(Locale.ROOT);
    }

    private static CreatorSalesDtos.Metric metric(
            String label, String value, long current, long previous, boolean lowerIsBetter
    ) {
        var comparison = CreatorReportingSupport.comparison(current, previous, lowerIsBetter);
        return new CreatorSalesDtos.Metric(label, value, comparison.direction(), comparison.sentiment(), comparison.text());
    }

    private enum Event { PAID, FAILED, REFUNDED }
    private static Instant timestamp(CommerceOrder order, Event event) {
        return switch (event) { case PAID -> order.getPaidAt(); case FAILED -> order.getFailedAt(); case REFUNDED -> order.getRefundedAt(); };
    }
    private static long sum(List<CommerceOrder> orders, CommerceOrderStatus status, ReportingWindow window, Event event) {
        return orders.stream().filter(order -> order.getStatus() == status).filter(order -> window.current(timestamp(order, event)))
                .mapToLong(CommerceOrder::getTotalMinor).sum();
    }
    private static long sumPrevious(List<CommerceOrder> orders, CommerceOrderStatus status, ReportingWindow window, Event event) {
        return orders.stream().filter(order -> order.getStatus() == status).filter(order -> window.previous(timestamp(order, event)))
                .mapToLong(CommerceOrder::getTotalMinor).sum();
    }
    private static long count(List<CommerceOrder> orders, CommerceOrderStatus status, ReportingWindow window, Event event, boolean previous) {
        return orders.stream().filter(order -> order.getStatus() == status)
                .filter(order -> previous ? window.previous(timestamp(order, event)) : window.current(timestamp(order, event))).count();
    }
    private static UUID parseUuid(String value, String field) {
        try { return UUID.fromString(value); } catch (IllegalArgumentException ex) { throw new IllegalArgumentException(field + " must be a UUID"); }
    }
    private static void validatePage(int page, int pageSize) {
        if (page < 0) throw new IllegalArgumentException("page must be at least 0");
        if (pageSize < 1 || pageSize > 100) throw new IllegalArgumentException("pageSize must be between 1 and 100");
    }
}

