   int delta=storageDeletes()-before;detail.put("storage_delete_calls_after_request",delta);detail.put("delete_invoked_keys",mockingDetails(spaces).getInvocations().stream().filter(i->i.getMethod().getName().equals("delete")).skip(before).map(i->i.getArgument(0)).toList());
   if(requester==other){var after=read(p);detail.put("gallery_after",after.path("galleryImages"));require(after.path("galleryImages").equals(baseline),"403 database rollback keeps all media metadata");require(count("product_media","product_id",p)==2,"403 retains two media rows");require(delta==0,"403 must not issue external storage deletes, actual="+delta);}
   else{call("GET","/api/products/"+p,null,owner,404);require(count("product_media","product_id",p)==0,"Allowed delete removes media rows");require(delta==2,"Allowed delete performs two storage cleanups");}
  }catch(Throwable t){status="Fail";detail.put("error",t.toString());}
  detail.put("status",status);detail.put("http_observations",observations.size()-start);mediaChecks.add(detail);System.out.println(name+": "+status.toUpperCase());
 }
 public static void main(String[] args)throws Exception{
  var t=new MigratedMediaDeletionQa();var manager=new TestContextManager(MigratedMediaDeletionQa.class);manager.prepareTestInstance(t);
  try{
   t.require(t.db.queryForObject("SELECT current_database()",String.class).equals("vpqa_cascades"),"Disposable database only");t.require(t.db.queryForObject("SELECT count(*) FROM databasechangelog",Integer.class)==40,"All40 migrations");
   t.owner=t.user("media-delete-owner@example.invalid","CREATOR");t.admin=t.user("media-delete-admin@example.invalid","ADMIN");t.other=t.user("media-delete-nonowner@example.invalid","CREATOR");
   doAnswer(i->{var stream=(java.io.InputStream)i.getArgument(1);t.require(stream.readAllBytes().length==t.png.length,"Raw fixture stream reaches adapter");return null;}).when(t.spaces).upload(anyString(),any(),anyLong(),anyString());
   for(String type:List.of("COURSE","DOWNLOAD","CONSULTATION","MEMBERSHIP"))for(User role:List.of(t.other,t.owner,t.admin))t.attempt(type,role);
   verifyNoInteractions(t.mail);var out=new LinkedHashMap<String,Object>();out.put("database","Actual private PostgreSQL15.19 with40 migrations");out.put("scenarios",t.mediaChecks);out.put("observations",t.observations);out.put("real_external_requests",0);out.put("mock_storage_upload_calls",mockingDetails(t.spaces).getInvocations().stream().filter(i->i.getMethod().getName().equals("upload")).count());out.put("mock_storage_delete_calls",t.storageDeletes());
   Files.writeString(Path.of("/private/tmp/vpqa-pg-media-deletion-observations.json"),t.mapper.writerWithDefaultPrettyPrinter().writeValueAsString(out));System.out.println("Recorded "+t.mediaChecks.size()+" assessments and "+t.observations.size()+" HTTP observations");
