package com.myproject.video.video_platform.exception;

import com.myproject.video.video_platform.dto.authetication.ErrorResponse;
import com.myproject.video.video_platform.dto.authetication.ValidationErrorResponse;
import com.myproject.video.video_platform.exception.auth.AuthenticationException;
import com.myproject.video.video_platform.exception.auth.CsrfException;
import com.myproject.video.video_platform.exception.auth.InvalidTokenException;
import com.myproject.video.video_platform.exception.auth.TokenExpiredException;
import com.myproject.video.video_platform.exception.auth.UserAlreadyExistingException;
import com.myproject.video.video_platform.exception.commerce.CommerceException;
import com.myproject.video.video_platform.exception.email.EmailSendingException;
import com.myproject.video.video_platform.exception.product.InvalidProductTypeException;
import com.myproject.video.video_platform.exception.product.PaymentRequiredException;
import com.myproject.video.video_platform.exception.product.ProductPublicationValidationException;
import com.myproject.video.video_platform.exception.product.ProductMediaException;
import com.myproject.video.video_platform.exception.product.QuizValidationException;
import com.myproject.video.video_platform.exception.product.ResourceNotFoundException;
import com.myproject.video.video_platform.exception.product.UnsupportedProductOperationException;
import com.myproject.video.video_platform.exception.user.UserNotFoundException;
import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;
import org.springframework.security.access.AccessDeniedException;
import org.springframework.validation.FieldError;
import org.springframework.web.bind.MethodArgumentNotValidException;
import org.springframework.web.bind.annotation.ExceptionHandler;
import org.springframework.web.bind.annotation.RestControllerAdvice;

import java.util.HashMap;
import java.util.List;
import java.util.Map;

@RestControllerAdvice
public class GlobalExceptionHandler {

    @ExceptionHandler(CommerceException.class)
    public ResponseEntity<ErrorResponse> handleCommerceException(CommerceException ex) {
        ErrorResponse error = new ErrorResponse(ex.getMessage(), ex.getStatus().value());
        return new ResponseEntity<>(error, ex.getStatus());
    }

    @ExceptionHandler(AuthenticationException.class)
    public ResponseEntity<ErrorResponse> handleAuthenticationException(AuthenticationException ex) {
        ErrorResponse error = new ErrorResponse(ex.getMessage(), HttpStatus.UNAUTHORIZED.value());
        return new ResponseEntity<>(error, HttpStatus.UNAUTHORIZED);
    }

    @ExceptionHandler(TokenExpiredException.class)
    public ResponseEntity<ErrorResponse> handleTokenExpiredException(TokenExpiredException ex) {
        ErrorResponse error = new ErrorResponse(ex.getMessage(), HttpStatus.UNAUTHORIZED.value());
        return new ResponseEntity<>(error, HttpStatus.UNAUTHORIZED);
    }

    @ExceptionHandler(Exception.class)
    public ResponseEntity<ErrorResponse> handleGenericException(Exception ex) {
        ErrorResponse error = new ErrorResponse(ex.getMessage(), HttpStatus.BAD_REQUEST.value());
        return new ResponseEntity<>(error, HttpStatus.BAD_REQUEST);
    }

    @ExceptionHandler(UserNotFoundException.class)
    public ResponseEntity<ErrorResponse> handleUserNotFoundException(UserNotFoundException ex) {
        ErrorResponse error = new ErrorResponse(ex.getMessage(), HttpStatus.NOT_FOUND.value());
        return new ResponseEntity<>(error, HttpStatus.NOT_FOUND);
    }

    @ExceptionHandler(EmailSendingException.class)
    public ResponseEntity<ErrorResponse> handleEmailSendingException(EmailSendingException ex) {
        ErrorResponse error = new ErrorResponse(ex.getMessage(), HttpStatus.BAD_REQUEST.value());
        return new ResponseEntity<>(error, HttpStatus.BAD_REQUEST);
    }

    @ExceptionHandler(MethodArgumentNotValidException.class)
    public ResponseEntity<ValidationErrorResponse> handleValidationExceptions(
            MethodArgumentNotValidException ex) {

        // Collect all field errors
        List<FieldError> fieldErrors = ex.getBindingResult().getFieldErrors();

        // Build a list or map of field -> error messages
        Map<String, String> errors = new HashMap<>();
        for (FieldError fieldError : fieldErrors) {
            errors.put(fieldError.getField(), fieldError.getDefaultMessage());
        }

        ValidationErrorResponse response = new ValidationErrorResponse(
                "Validation failed",
                errors
        );

        return new ResponseEntity<>(response, HttpStatus.BAD_REQUEST);
    }

    @ExceptionHandler(CsrfException.class)
    public ResponseEntity<ErrorResponse> handleCsrfException(CsrfException ex) {
        ErrorResponse error = new ErrorResponse(ex.getMessage(), HttpStatus.FORBIDDEN.value());
        return new ResponseEntity<>(error, HttpStatus.FORBIDDEN);
    }

    @ExceptionHandler(AccessDeniedException.class)
    public ResponseEntity<ErrorResponse> handleAccessDeniedException(AccessDeniedException ex) {
        ErrorResponse error = new ErrorResponse("Access Denied", HttpStatus.FORBIDDEN.value());
        return new ResponseEntity<>(error, HttpStatus.FORBIDDEN);
    }

    @ExceptionHandler(UserAlreadyExistingException.class)
    public ResponseEntity<ErrorResponse> handleUserAlreadyExistingException(UserAlreadyExistingException ex) {
        ErrorResponse error = new ErrorResponse(ex.getMessage(), HttpStatus.BAD_REQUEST.value());
        return new ResponseEntity<>(error, HttpStatus.FORBIDDEN);
    }

    @ExceptionHandler(InvalidProductTypeException.class)
    public ResponseEntity<ErrorResponse> handleInvalidProductTypeException(InvalidProductTypeException ex) {
        ErrorResponse error = new ErrorResponse(ex.getMessage(), HttpStatus.BAD_REQUEST.value());
        return new ResponseEntity<>(error, HttpStatus.BAD_REQUEST);
    }

    @ExceptionHandler(InvalidTokenException.class)
    public ResponseEntity<ErrorResponse> handleInvalidTokenException(InvalidTokenException ex) {
        ErrorResponse error = new ErrorResponse(ex.getMessage(), HttpStatus.UNAUTHORIZED.value());
        return new ResponseEntity<>(error, HttpStatus.UNAUTHORIZED);
    }

    @ExceptionHandler(ResourceNotFoundException.class)
    public ResponseEntity<ErrorResponse> handleInvalidTokenException(ResourceNotFoundException ex) {
        ErrorResponse error = new ErrorResponse(ex.getMessage(), HttpStatus.NOT_FOUND.value());
        return new ResponseEntity<>(error, HttpStatus.NOT_FOUND);
    }

    @ExceptionHandler(QuizValidationException.class)
    public ResponseEntity<ValidationErrorResponse> handleQuizValidationException(QuizValidationException ex) {
        ValidationErrorResponse response = new ValidationErrorResponse(
                ex.getMessage(),
                ex.getErrors()
        );
        return new ResponseEntity<>(response, HttpStatus.BAD_REQUEST);
    }

    @ExceptionHandler(ProductPublicationValidationException.class)
    public ResponseEntity<ValidationErrorResponse> handlePublicationValidation(
            ProductPublicationValidationException ex
    ) {
        return new ResponseEntity<>(
                new ValidationErrorResponse(ex.getMessage(), ex.getErrors()),
                HttpStatus.UNPROCESSABLE_ENTITY
        );
    }

    @ExceptionHandler(ProductMediaException.class)
    public ResponseEntity<ErrorResponse> handleProductMediaException(ProductMediaException ex) {
        return new ResponseEntity<>(new ErrorResponse(ex.getMessage(), HttpStatus.BAD_REQUEST.value()), HttpStatus.BAD_REQUEST);
    }

    @ExceptionHandler(UnsupportedProductOperationException.class)
    public ResponseEntity<ErrorResponse> handleUnsupportedProductOperationException(
            UnsupportedProductOperationException ex
    ) {
        ErrorResponse error = new ErrorResponse(ex.getMessage(), HttpStatus.CONFLICT.value());
        return new ResponseEntity<>(error, HttpStatus.CONFLICT);
    }

    @ExceptionHandler(PaymentRequiredException.class)
    public ResponseEntity<ErrorResponse> handlePaymentRequiredException(PaymentRequiredException ex) {
        ErrorResponse error = new ErrorResponse(ex.getMessage(), HttpStatus.PAYMENT_REQUIRED.value());
        return new ResponseEntity<>(error, HttpStatus.PAYMENT_REQUIRED);
    }
}

package com.myproject.video.video_platform.service.product.strategy_handler;

import com.myproject.video.video_platform.common.converter.product.CourseProductConverter;
import com.myproject.video.video_platform.common.enums.products.ProductType;
import com.myproject.video.video_platform.dto.products.AbstractProductRequestDto;
import com.myproject.video.video_platform.dto.products.AbstractProductResponseDto;
import com.myproject.video.video_platform.dto.products.course.CourseProductRequestDto;
import com.myproject.video.video_platform.entity.products.course.CourseProduct;
import com.myproject.video.video_platform.entity.user.User;
import com.myproject.video.video_platform.exception.product.ResourceNotFoundException;
import com.myproject.video.video_platform.repository.products.course.CourseProductRepository;
import com.myproject.video.video_platform.service.product.ProductAuthorizationService;
import com.myproject.video.video_platform.service.product.ProductPublicationValidator;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.springframework.stereotype.Component;
import org.springframework.transaction.annotation.Transactional;

import java.util.Optional;
import java.util.UUID;

@Slf4j
@Component
@RequiredArgsConstructor
public class CourseProductHandler implements ProductTypeHandler {

    private final CourseProductRepository courseRepo;
    private final CourseProductConverter converter;
    private final ProductAuthorizationService productAuthorizationService;
    private final ProductPublicationValidator publicationValidator;

    @Override
    public ProductType getSupportedType() {
        return ProductType.COURSE;
    }

    @Override
    @Transactional(readOnly = true)
    public AbstractProductResponseDto getProductById(String productId) {
        UUID id = UUID.fromString(productId);
        CourseProduct course = courseRepo.findFullById(id)
                .orElseThrow(() -> new ResourceNotFoundException("Course not found: " + productId));
        return converter.mapCourseToResponse(course);
    }

    @Override
    @Transactional
    public AbstractProductResponseDto createProduct(AbstractProductRequestDto baseDto) {
        CourseProductRequestDto dto = (CourseProductRequestDto) baseDto;
        log.info("Creating a new Course: {}", dto.getName());

        User owner = productAuthorizationService.resolveOwnerForCreate(dto);

        CourseProduct courseEntity = converter.mapCourseCreateDtoToEntity(dto, owner);
        publicationValidator.validate(courseEntity);
        CourseProduct saved = courseRepo.save(courseEntity);
        return converter.mapCourseToResponse(saved);
    }

    @Override
    @Transactional
    public AbstractProductResponseDto updateProduct(AbstractProductRequestDto baseDto) {
        CourseProductRequestDto dto = (CourseProductRequestDto) baseDto;
        log.info("Updating Course: {}", dto.getName());

        UUID id = UUID.fromString(dto.getId());
        CourseProduct existing = courseRepo.findById(id)
                .orElseThrow(() -> new ResourceNotFoundException("Course not found: " + dto.getId()));

        productAuthorizationService.requireOwnerOrAdmin(existing);

        converter.applyCourseUpdateDto(existing, dto);
        publicationValidator.validate(existing);
        CourseProduct saved = courseRepo.save(existing);
        return converter.mapCourseToResponse(saved);
    }

    @Override
    public void deleteProduct(String userId, String productId) {
        Optional<CourseProduct> courseProductOptional = courseRepo.findById(UUID.fromString(productId));
        if (courseProductOptional.isPresent()) {
            productAuthorizationService.requireOwnerOrAdmin(courseProductOptional.get());

            courseRepo.delete(courseProductOptional.get());
            log.info("Deleted succesfully a DownloadProduct: {}", productId);
        } else
            throw new ResourceNotFoundException("DownloadProduct not found for ID: " + productId);
    }
}

package com.myproject.video.video_platform.service.product.strategy_handler;

import com.myproject.video.video_platform.common.converter.product.DownloadProductConverter;
import com.myproject.video.video_platform.common.enums.products.ProductType;
import com.myproject.video.video_platform.dto.products.AbstractProductRequestDto;
import com.myproject.video.video_platform.dto.products.AbstractProductResponseDto;
import com.myproject.video.video_platform.dto.products.download.DownloadProductRequestDto;
import com.myproject.video.video_platform.entity.products.download.DownloadProduct;
import com.myproject.video.video_platform.entity.user.User;
import com.myproject.video.video_platform.exception.product.ResourceNotFoundException;
import com.myproject.video.video_platform.repository.products.download.DownloadProductRepository;
import com.myproject.video.video_platform.service.product.ProductAuthorizationService;
import com.myproject.video.video_platform.service.product.ProductPublicationValidator;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.springframework.stereotype.Component;

import java.util.Optional;
import java.util.UUID;

@Slf4j
@Component
@RequiredArgsConstructor
public class DownloadProductHandler implements ProductTypeHandler {

    private final DownloadProductRepository downloadProductRepository;
    private final DownloadProductConverter downloadProductConverter;
    private final ProductAuthorizationService productAuthorizationService;
    private final ProductPublicationValidator publicationValidator;


    @Override
    public ProductType getSupportedType() {
        return ProductType.DOWNLOAD;
    }

    @Override
    public AbstractProductResponseDto getProductById(String productId) {
        UUID id = UUID.fromString(productId);
        DownloadProduct product = downloadProductRepository.findFullById(id)
                .orElseThrow(() -> new ResourceNotFoundException("DownloadProduct not found for ID: " + productId));
        return downloadProductConverter.mapDownloadProductToResponse(product);
    }

    @Override
    public AbstractProductResponseDto createProduct(AbstractProductRequestDto dto) {
        log.info("Creating a DownloadProduct: {}", dto.getName());

        User owner = productAuthorizationService.resolveOwnerForCreate(dto);

        DownloadProduct product = downloadProductConverter
                .mapDownloadProductRequestDtoToEntity((DownloadProductRequestDto) dto, owner);
        publicationValidator.validate(product);
        DownloadProduct saved = downloadProductRepository.save(product);

        log.info("Created succesfully a DownloadProduct: {}", dto.getName());
        return downloadProductConverter.mapDownloadProductToResponse(saved);
    }

    @Override
    public AbstractProductResponseDto updateProduct(AbstractProductRequestDto dto) {
        log.info("Updating a download product: {}", dto.getName());

        Optional<DownloadProduct> downloadProductOptional =
                downloadProductRepository.findById(UUID.fromString(dto.getId()));

        if (downloadProductOptional.isPresent()) {
            DownloadProduct downloadProduct = downloadProductOptional.get();

            productAuthorizationService.requireOwnerOrAdmin(downloadProduct);

            DownloadProduct updatedProduct = downloadProductConverter.mapDownloadProductUpdate(
                    downloadProduct,
                    (DownloadProductRequestDto) dto
            );
            publicationValidator.validate(updatedProduct);

            updatedProduct = downloadProductRepository.save(updatedProduct);

            log.info("Updated succesfully a DownloadProduct: {}", dto.getName());
            return downloadProductConverter.mapDownloadProductToResponse(updatedProduct);
        } else
            throw new ResourceNotFoundException("DownloadProduct not found for ID: " + dto.getId());
    }

    @Override
    public void deleteProduct(String userId, String productId) {
        Optional<DownloadProduct> downloadProductOptional = downloadProductRepository.findById(UUID.fromString(productId));
        if (downloadProductOptional.isPresent()) {
            productAuthorizationService.requireOwnerOrAdmin(downloadProductOptional.get());

            downloadProductRepository.delete(downloadProductOptional.get());
            log.info("Deleted succesfully a DownloadProduct: {}", productId);
        } else
            throw new ResourceNotFoundException("DownloadProduct not found for ID: " + productId);
    }
}

package com.myproject.video.video_platform.service.product.strategy_handler;

import com.myproject.video.video_platform.common.converter.product.ConsultationProductConverter;
import com.myproject.video.video_platform.common.enums.products.ProductType;
import com.myproject.video.video_platform.dto.products.AbstractProductRequestDto;
import com.myproject.video.video_platform.dto.products.AbstractProductResponseDto;
import com.myproject.video.video_platform.dto.products.consultation.ConsultationProductRequestDto;
import com.myproject.video.video_platform.entity.products.consultation.ConsultationProduct;
import com.myproject.video.video_platform.entity.user.User;
import com.myproject.video.video_platform.exception.product.ResourceNotFoundException;
import com.myproject.video.video_platform.repository.products.consultation.ConsultationProductRepository;
import com.myproject.video.video_platform.service.product.ProductAuthorizationService;
import com.myproject.video.video_platform.service.product.ProductPublicationValidator;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.springframework.stereotype.Component;
import org.springframework.transaction.annotation.Transactional;

import java.util.Optional;
import java.util.UUID;

@Slf4j
@Component
@RequiredArgsConstructor
public class ConsultationProductHandler implements ProductTypeHandler {

    private final ConsultationProductRepository repo;
    private final ConsultationProductConverter converter;
    private final ProductAuthorizationService productAuthorizationService;
    private final ProductPublicationValidator publicationValidator;

    @Override
    public ProductType getSupportedType() {
        return ProductType.CONSULTATION;
    }

    @Override
    @Transactional
    public AbstractProductResponseDto createProduct(AbstractProductRequestDto dto) {
        User owner = productAuthorizationService.resolveOwnerForCreate(dto);

        ConsultationProduct entity = converter.fromDto((ConsultationProductRequestDto) dto, owner);
        publicationValidator.validate(entity);
        ConsultationProduct saved = repo.save(entity);

        return converter.toDto(saved);
    }

    @Override
    @Transactional(readOnly = true)
    public AbstractProductResponseDto getProductById(String productId) {
        ConsultationProduct entity = repo.findById(UUID.fromString(productId))
                .orElseThrow(() -> new ResourceNotFoundException("Consultation not found: " + productId));
        return converter.toDto(entity);
    }

    @Override
    @Transactional
    public AbstractProductResponseDto updateProduct(AbstractProductRequestDto dto) {
        String id = dto.getId();
        ConsultationProduct existing = repo.findById(UUID.fromString(id))
                .orElseThrow(() -> new ResourceNotFoundException("Consultation not found: " + id));

        productAuthorizationService.requireOwnerOrAdmin(existing);

        converter.updateEntityFromDto(
                (ConsultationProductRequestDto) dto,
                existing
        );
        publicationValidator.validate(existing);

        ConsultationProduct updated = repo.save(existing);
        return converter.toDto(updated);
    }

    @Override
    @Transactional
    public void deleteProduct(String userId, String productId) {
        log.info("Deleting Consultation: {}", productId);

        Optional<ConsultationProduct> existing = repo.findById(UUID.fromString(productId));

        if (existing.isEmpty())
            throw new ResourceNotFoundException("DownloadProduct not found for ID: " + productId);
        else {
            productAuthorizationService.requireOwnerOrAdmin(existing.get());

            repo.delete(existing.get());
            log.info("Deleted succesfully a Consultation Product: {}", productId);
        }

    }
}

package com.myproject.video.video_platform.service.product.strategy_handler;

import com.myproject.video.video_platform.common.converter.product.MembershipProductConverter;
import com.myproject.video.video_platform.common.enums.products.ProductType;
import com.myproject.video.video_platform.dto.products.AbstractProductRequestDto;
import com.myproject.video.video_platform.dto.products.AbstractProductResponseDto;
import com.myproject.video.video_platform.dto.products.membership.MembershipProductRequestDto;
import com.myproject.video.video_platform.entity.products.membership.MembershipProduct;
import com.myproject.video.video_platform.entity.user.User;
import com.myproject.video.video_platform.exception.product.ResourceNotFoundException;
import com.myproject.video.video_platform.repository.products.membership.MembershipProductRepository;
import com.myproject.video.video_platform.repository.products.membership.MembershipContentRepository;
import com.myproject.video.video_platform.repository.products.membership.MembershipFeedEntryRepository;
import com.myproject.video.video_platform.service.product.ProductAuthorizationService;
import com.myproject.video.video_platform.service.product.ProductPublicationValidator;
import lombok.RequiredArgsConstructor;
import org.springframework.stereotype.Component;
import org.springframework.transaction.annotation.Transactional;

import java.util.UUID;

@Component
@RequiredArgsConstructor
public class MembershipProductHandler implements ProductTypeHandler {
    private final MembershipProductRepository repository;
    private final MembershipProductConverter converter;
    private final ProductAuthorizationService authorizationService;
    private final MembershipContentRepository contentRepository;
    private final MembershipFeedEntryRepository feedRepository;
    private final ProductPublicationValidator publicationValidator;

    @Override
    public ProductType getSupportedType() {
        return ProductType.MEMBERSHIP;
    }

    @Override
    @Transactional
    public AbstractProductResponseDto createProduct(AbstractProductRequestDto baseDto) {
        MembershipProductRequestDto dto = (MembershipProductRequestDto) baseDto;
        User owner = authorizationService.resolveOwnerForCreate(dto);
        MembershipProduct product = converter.fromCreate(dto, owner);
        publicationValidator.validate(product);
        return converter.toResponse(repository.saveAndFlush(product));
    }

    @Override
    @Transactional(readOnly = true)
    public AbstractProductResponseDto getProductById(String productId) {
        MembershipProduct product = find(productId);
        return converter.toResponse(product);
    }

    @Override
    @Transactional
    public AbstractProductResponseDto updateProduct(AbstractProductRequestDto baseDto) {
        MembershipProductRequestDto dto = (MembershipProductRequestDto) baseDto;
        MembershipProduct product = find(dto.getId());
        authorizationService.requireOwnerOrAdmin(product);
        converter.applyUpdate(product, dto);
        publicationValidator.validate(product);
        return converter.toResponse(repository.save(product));
    }

    @Override
    @Transactional
    public void deleteProduct(String userId, String productId) {
        MembershipProduct product = find(productId);
        authorizationService.requireOwnerOrAdmin(product);
        feedRepository.deleteAllByMembershipId(product.getId());
        contentRepository.deleteAllByMembershipId(product.getId());
        repository.delete(product);
    }

    private MembershipProduct find(String productId) {
        return repository.findById(UUID.fromString(productId))
                .orElseThrow(() -> new ResourceNotFoundException("Membership not found: " + productId));
    }
}

package com.myproject.video.video_platform.controller.product;

import com.myproject.video.video_platform.dto.products.media.*;
import com.myproject.video.video_platform.service.product.ProductMediaService;
import jakarta.servlet.http.HttpServletRequest;
import lombok.RequiredArgsConstructor;
import io.swagger.v3.oas.annotations.Operation;
import io.swagger.v3.oas.annotations.tags.Tag;
import org.springframework.http.ResponseEntity;
import org.springframework.security.access.prepost.PreAuthorize;
import org.springframework.web.bind.annotation.*;

import java.io.IOException;
import java.util.List;
import java.util.UUID;

@RestController
@RequestMapping("/api/products")
@RequiredArgsConstructor
@PreAuthorize("hasAnyRole('CREATOR','ADMIN')")
@Tag(name = "Product Media", description = "Owner/Admin raw uploads proxied to DigitalOcean Spaces.")
public class ProductMediaController {
    private final ProductMediaService service;

    @PostMapping("/image")
    @Operation(summary = "Replace a Product thumbnail", description = "Accepts a raw JPEG, PNG, WebP, or GIF body up to the configured image limit.")
    public ResponseEntity<String> uploadThumbnail(@RequestParam UUID productId, HttpServletRequest request) throws IOException {
        return ResponseEntity.ok(service.replaceThumbnail(productId, request.getInputStream(), request.getContentLengthLong(), request.getContentType()));
    }
    @DeleteMapping("/image")
    @Operation(summary = "Remove a Product thumbnail")
    public ResponseEntity<Void> deleteThumbnail(@RequestParam UUID productId) { service.removeThumbnail(productId); return ResponseEntity.noContent().build(); }
    @PostMapping("/{id}/media/gallery")
    @Operation(summary = "Add a Product gallery image")
    public ProductGalleryImageDto uploadGallery(@PathVariable UUID id, HttpServletRequest request) throws IOException {
        return service.addGallery(id, request.getInputStream(), request.getContentLengthLong(), request.getContentType());
    }
    @DeleteMapping("/{id}/media/gallery/{imageId}")
    @Operation(summary = "Remove a Product gallery image")
    public ResponseEntity<Void> deleteGallery(@PathVariable UUID id, @PathVariable UUID imageId) { service.removeGallery(id, imageId); return ResponseEntity.noContent().build(); }
    @PutMapping("/{id}/media/gallery/order")
    @Operation(summary = "Replace the complete gallery order", description = "imageIds must contain every current gallery image exactly once.")
    public List<ProductGalleryImageDto> reorder(@PathVariable UUID id, @RequestBody GalleryOrderRequest request) { return service.reorder(id, request.getImageIds()); }
    @PostMapping("/{id}/media/promo-video")
    @Operation(summary = "Replace a Product promotional video", description = "Accepts a raw MP4 or WebM body up to the configured video limit.")
    public ProductPromoVideoDto uploadPromo(@PathVariable UUID id, HttpServletRequest request) throws IOException {
        return service.replacePromo(id, request.getInputStream(), request.getContentLengthLong(), request.getContentType());
    }
    @DeleteMapping("/{id}/media/promo-video")
    @Operation(summary = "Remove a Product promotional video")
    public ResponseEntity<Void> deletePromo(@PathVariable UUID id) { service.removePromo(id); return ResponseEntity.noContent().build(); }
}

package com.myproject.video.video_platform.service.product;

import com.myproject.video.video_platform.dto.products.AbstractProductResponseDto;
import com.myproject.video.video_platform.dto.products.media.ProductGalleryImageDto;
import com.myproject.video.video_platform.dto.products.media.ProductPromoVideoDto;
import com.myproject.video.video_platform.entity.products.Product;
import com.myproject.video.video_platform.entity.products.ProductMedia;
import com.myproject.video.video_platform.exception.product.ProductMediaException;
import com.myproject.video.video_platform.exception.product.ResourceNotFoundException;
import com.myproject.video.video_platform.repository.products.ProductMediaRepository;
import com.myproject.video.video_platform.repository.products.ProductRepository;
import com.myproject.video.video_platform.service.digitalocean.SpacesS3Service;
import lombok.extern.slf4j.Slf4j;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import java.io.InputStream;
import java.util.*;

@Service
@Slf4j
public class ProductMediaService {
    private static final Set<String> IMAGE_TYPES = Set.of("image/jpeg", "image/png", "image/webp", "image/gif");
    private static final Set<String> VIDEO_TYPES = Set.of("video/mp4", "video/webm");
    private final ProductRepository products;
    private final ProductMediaRepository media;
    private final ProductAuthorizationService authorization;
    private final SpacesS3Service spaces;
    private final String cdnEndpoint;
    private final long imageMaxBytes;
    private final long videoMaxBytes;
    private final int galleryMaxItems;

    public ProductMediaService(ProductRepository products, ProductMediaRepository media,
                               ProductAuthorizationService authorization, SpacesS3Service spaces,
                               @Value("${digitalocean.spaces.cdnEndpointUrl}") String cdnEndpoint,
                               @Value("${app.product-media.image-max-bytes:10485760}") long imageMaxBytes,
                               @Value("${app.product-media.video-max-bytes:104857600}") long videoMaxBytes,
                               @Value("${app.product-media.gallery-max-items:20}") int galleryMaxItems) {
        this.products = products; this.media = media; this.authorization = authorization; this.spaces = spaces;
        this.cdnEndpoint = cdnEndpoint.replaceAll("/+$", "");
        this.imageMaxBytes = imageMaxBytes; this.videoMaxBytes = videoMaxBytes; this.galleryMaxItems = galleryMaxItems;
    }

    @Transactional
    public String replaceThumbnail(UUID productId, InputStream body, long size, String type) {
        Product product = owned(productId); type = validateFile(type, size, IMAGE_TYPES, imageMaxBytes);
        ProductMedia created = upload(product, ProductMedia.Kind.THUMBNAIL, body, size, type, null);
        ProductMedia previous = media.findByProductIdAndKind(productId, ProductMedia.Kind.THUMBNAIL).orElse(null);
        removeReference(previous); media.save(created); product.setImage(created.getCdnUrl()); products.save(product);
        return created.getCdnUrl();
    }

    @Transactional
    public void removeThumbnail(UUID productId) {
        Product product = owned(productId);
        ProductMedia previous = media.findByProductIdAndKind(productId, ProductMedia.Kind.THUMBNAIL).orElse(null);
        product.setImage(null); products.save(product); removeReference(previous);
    }

    @Transactional
    public ProductGalleryImageDto addGallery(UUID productId, InputStream body, long size, String type) {
        Product product = owned(productId); type = validateFile(type, size, IMAGE_TYPES, imageMaxBytes);
        long count = media.countByProductIdAndKind(productId, ProductMedia.Kind.GALLERY_IMAGE);
        if (count >= galleryMaxItems) throw new ProductMediaException("Gallery limit is " + galleryMaxItems + " images");
        return gallery(media.save(upload(product, ProductMedia.Kind.GALLERY_IMAGE, body, size, type, (int) count)));
    }

    @Transactional
    public void removeGallery(UUID productId, UUID imageId) {
        owned(productId);
        ProductMedia item = media.findByIdAndProductIdAndKind(imageId, productId, ProductMedia.Kind.GALLERY_IMAGE)
                .orElseThrow(() -> new ResourceNotFoundException("Gallery image not found: " + imageId));
        removeReference(item);
        List<ProductMedia> remaining = media.findAllByProductIdAndKindOrderByGalleryPositionAsc(productId, ProductMedia.Kind.GALLERY_IMAGE);
        for (int i = 0; i < remaining.size(); i++) remaining.get(i).setGalleryPosition(i);
        media.saveAll(remaining);
    }

    @Transactional
    public List<ProductGalleryImageDto> reorder(UUID productId, List<UUID> ids) {
        owned(productId);
        List<ProductMedia> current = media.findAllByProductIdAndKindOrderByGalleryPositionAsc(productId, ProductMedia.Kind.GALLERY_IMAGE);
        if (ids == null || ids.size() != current.size() || new HashSet<>(ids).size() != ids.size()
                || !new HashSet<>(ids).equals(current.stream().map(ProductMedia::getId).collect(java.util.stream.Collectors.toSet()))) {
            throw new ProductMediaException("Gallery order must contain every gallery image exactly once");
        }
        Map<UUID, ProductMedia> byId = new HashMap<>(); current.forEach(item -> byId.put(item.getId(), item));
        for (int i = 0; i < ids.size(); i++) byId.get(ids.get(i)).setGalleryPosition(i);
        media.saveAll(current);
        return ids.stream().map(byId::get).map(this::gallery).toList();
    }

    @Transactional
    public ProductPromoVideoDto replacePromo(UUID productId, InputStream body, long size, String type) {
        Product product = owned(productId); type = validateFile(type, size, VIDEO_TYPES, videoMaxBytes);
        ProductMedia created = upload(product, ProductMedia.Kind.PROMO_VIDEO, body, size, type, null);
        ProductMedia previous = media.findByProductIdAndKind(productId, ProductMedia.Kind.PROMO_VIDEO).orElse(null);
        removeReference(previous); media.save(created); return promo(created);
    }

    @Transactional
    public void removePromo(UUID productId) {
        owned(productId);
        removeReference(media.findByProductIdAndKind(productId, ProductMedia.Kind.PROMO_VIDEO).orElse(null));
    }

    @Transactional
    public void removeAll(UUID productId) {
        List<ProductMedia> all = media.findAllByProductId(productId);
        media.deleteAllByProductId(productId); media.flush();
        all.forEach(this::deleteObjectQuietly);
    }

    @Transactional(readOnly = true)
    public void enrich(UUID productId, AbstractProductResponseDto response) {
        response.setImageUrl(response.getImageUrl() != null ? response.getImageUrl() : products.findById(productId).map(Product::getImage).orElse(null));
        response.setGalleryImages(media.findAllByProductIdAndKindOrderByGalleryPositionAsc(productId, ProductMedia.Kind.GALLERY_IMAGE)
                .stream().map(this::gallery).toList());
        response.setPromoVideo(media.findByProductIdAndKind(productId, ProductMedia.Kind.PROMO_VIDEO).map(this::promo).orElse(null));
    }

    private Product owned(UUID id) {
        Product product = products.findById(id).orElseThrow(() -> new ResourceNotFoundException("Product not found: " + id));
        authorization.requireOwnerOrAdmin(product); return product;
    }

    private ProductMedia upload(Product product, ProductMedia.Kind kind, InputStream body, long size, String type, Integer position) {
        String extension = switch (type.toLowerCase(Locale.ROOT)) {
            case "image/jpeg" -> "jpg"; case "image/png" -> "png"; case "image/webp" -> "webp";
            case "image/gif" -> "gif"; case "video/mp4" -> "mp4"; case "video/webm" -> "webm";
            default -> throw new ProductMediaException("Unsupported media type");
        };
        String filename = UUID.randomUUID() + "." + extension;
        String key = "products/" + product.getUser().getUserId() + "/" + product.getId() + "/" + kind.name().toLowerCase(Locale.ROOT) + "/" + filename;
        try { spaces.upload(key, body, size, type); }
        catch (RuntimeException ex) { throw new ProductMediaException("Product media upload failed", ex); }
        ProductMedia item = new ProductMedia(); item.setProductId(product.getId()); item.setKind(kind); item.setObjectKey(key);
        item.setCdnUrl(cdnEndpoint + "/" + key); item.setFileName(filename); item.setMimeType(type); item.setSize(size);
        item.setGalleryPosition(position == null ? -1 : position); item.setStatus(ProductMedia.Status.READY); return item;
    }

    private static String validateFile(String type, long size, Set<String> allowed, long maximum) {
        String normalized = type == null ? "" : type.split(";", 2)[0].trim().toLowerCase(Locale.ROOT);
        if (!allowed.contains(normalized)) throw new ProductMediaException("Unsupported media type: " + type);
        if (size <= 0 || size > maximum) throw new ProductMediaException("Media size must be between 1 and " + maximum + " bytes");
        return normalized;
    }

    private void removeReference(ProductMedia item) {
        if (item == null) return; media.delete(item); media.flush(); deleteObjectQuietly(item);
    }
    private void deleteObjectQuietly(ProductMedia item) {
        try { spaces.delete(item.getObjectKey()); }
        catch (RuntimeException ex) { log.warn("Failed to remove orphaned Product media object {}", item.getObjectKey(), ex); }
    }
    private ProductGalleryImageDto gallery(ProductMedia item) {
        return new ProductGalleryImageDto(item.getId(), item.getCdnUrl(), item.getFileName(), item.getMimeType(), item.getSize(),
                item.getGalleryPosition(), null, item.getStatus().name());
    }
    private ProductPromoVideoDto promo(ProductMedia item) {
        return new ProductPromoVideoDto(item.getId(), item.getCdnUrl(), item.getFileName(), item.getMimeType(), item.getSize(), item.getStatus().name(), null);
    }
}

package com.myproject.video.video_platform.service.product;

import com.myproject.video.video_platform.common.enums.user.UserRole;
import com.myproject.video.video_platform.dto.products.AbstractProductRequestDto;
import com.myproject.video.video_platform.entity.products.Product;
import com.myproject.video.video_platform.entity.user.Role;
import com.myproject.video.video_platform.entity.user.User;
import com.myproject.video.video_platform.exception.user.UserNotFoundException;
import com.myproject.video.video_platform.repository.auth.UserRepository;
import com.myproject.video.video_platform.service.user.CurrentUserService;
import org.springframework.security.access.AccessDeniedException;
import org.springframework.security.core.Authentication;
import org.springframework.security.core.context.SecurityContextHolder;
import org.springframework.stereotype.Service;

import java.util.UUID;

@Service
public class ProductAuthorizationService {

    private final CurrentUserService currentUserService;
    private final UserRepository userRepository;

    public ProductAuthorizationService(CurrentUserService currentUserService,
                                       UserRepository userRepository) {
        this.currentUserService = currentUserService;
        this.userRepository = userRepository;
    }

    public boolean isCurrentUserAdmin() {
        Authentication auth = SecurityContextHolder.getContext().getAuthentication();
        return auth != null && auth.getAuthorities().stream()
                .anyMatch(authority -> UserRole.ADMIN.authority().equals(authority.getAuthority()));
    }

    public UUID getCurrentUserId() {
        return currentUserService.getCurrentUserId();
    }

    public void requireOwnerOrAdmin(Product product) {
        requireOwnerOrAdmin(product.getUser().getUserId());
    }

    public void requireOwnerOrAdmin(UUID ownerId) {
        if (isCurrentUserAdmin()) {
            return;
        }

        UUID currentUserId = currentUserService.getCurrentUserId();
        if (!ownerId.equals(currentUserId)) {
            throw new AccessDeniedException("You don’t own this product.");
        }
    }

    public User resolveOwnerForCreate(AbstractProductRequestDto dto) {
        if (isCurrentUserAdmin()) {
            if (dto.getUserId() == null || dto.getUserId().isBlank()) {
                throw new AccessDeniedException("Admin product creation requires a creator owner");
            }

            User owner = getUser(UUID.fromString(dto.getUserId()));
            if (!hasSingleRole(owner, UserRole.CREATOR)) {
                throw new AccessDeniedException("Product owner must have CREATOR role");
            }
            return owner;
        }

        UUID currentUserId = currentUserService.getCurrentUserId();
        User owner = getUser(currentUserId);
        dto.setUserId(currentUserId.toString());
        return owner;
    }

    private User getUser(UUID userId) {
        return userRepository.findById(userId)
                .orElseThrow(() -> new UserNotFoundException("User not found: " + userId));
    }

    private boolean hasSingleRole(User user, UserRole role) {
        return user.getRoles().size() == 1
                && user.getRoles().stream()
                .map(Role::getRoleName)
                .anyMatch(role.name()::equals);
    }
}

package com.myproject.video.video_platform.entity.products;

import jakarta.persistence.*;
import lombok.Getter;
import lombok.Setter;
import org.hibernate.annotations.CreationTimestamp;
import org.hibernate.annotations.UpdateTimestamp;

import java.time.LocalDateTime;
import java.util.UUID;

@Entity
@Table(name = "product_media")
@Getter
@Setter
public class ProductMedia {
    @Id @GeneratedValue private UUID id;
    @Column(name = "product_id", nullable = false) private UUID productId;
    @Enumerated(EnumType.STRING) @Column(nullable = false, length = 24) private Kind kind;
    @Column(name = "object_key", nullable = false, unique = true, length = 512) private String objectKey;
    @Column(name = "cdn_url", nullable = false, length = 2048) private String cdnUrl;
    @Column(name = "file_name", nullable = false) private String fileName;
    @Column(name = "mime_type", nullable = false, length = 100) private String mimeType;
    @Column(name = "file_size", nullable = false) private long size;
    @Column(name = "gallery_position") private Integer galleryPosition;
    @Enumerated(EnumType.STRING) @Column(nullable = false, length = 24) private Status status;
    @CreationTimestamp @Column(name = "created_at", nullable = false, updatable = false) private LocalDateTime createdAt;
    @UpdateTimestamp @Column(name = "updated_at") private LocalDateTime updatedAt;

    public enum Kind { THUMBNAIL, GALLERY_IMAGE, PROMO_VIDEO }
    public enum Status { READY }
}

