  var submit=call("POST","/api/lessons/"+l+"/quiz/submit",Map.of("answers",List.of(Map.of("questionId",q.path("id").asText(),"selectedOptionIds",List.of(opt.path("id").asText())))),owner,200);
  require(submit.path("passed").asBoolean(),"Quiz positive submission");
  require(count("quiz_attempts","lesson_id",l)==1,"Persisted quiz attempt before deletion");
  return new String[]{p,s,l,quiz.path("id").asText()};
 }
 long count(String table,String key,String id){return db.queryForObject("SELECT count(*) FROM "+table+" WHERE "+key+"=?::uuid",Long.class,id);}
 void goneQuiz(String[] f){require(count("course_quizzes","id",f[3])==0,"Quiz gone");require(count("quiz_attempts","lesson_id",f[2])==0,"Attempts gone");require(count("quiz_questions","quiz_id",f[3])==0,"Questions gone");}
 String[] downloadFixture()throws Exception{
  String p=product("DOWNLOAD","Cascade download"),s=section(p);
  String file=call("POST","/api/products/"+p+"/sections/"+s+"/files/confirm-upload",Map.of("fileName","fixture.pdf","fileSize",42,"fileType","application/pdf","key","synthetic-not-uploaded/fixture.pdf"),owner,201).path("fileId").asText();
  var before=call("GET","/api/products/"+p,null,owner,200);
  require(before.path("details").path("sections").get(0).path("files").size()==1,"One file metadata before deletion");
  return new String[]{p,s,file};
 }
 void courseDelete(String kind)throws Exception{
  var f=courseFixture();
  var baseline=call("GET","/api/products/"+f[0],null,owner,200).path("details").path("sections");
  String target=switch(kind){case "quiz"->"/api/lessons/"+f[2]+"/quiz";case "lesson"->"/api/products/"+f[0]+"/sections/"+f[1]+"/lessons/"+f[2];case "section"->"/api/products/"+f[0]+"/sections/"+f[1];default->"/api/products/"+f[0];};
  call("DELETE",target,null,actor,204);goneQuiz(f);
  call("GET","/api/lessons/"+f[2]+"/quiz",null,owner,404);
  call("GET","/api/lessons/"+f[2]+"/quiz/play",null,owner,404);
  if(kind.equals("product"))call("GET","/api/products/"+f[0],null,owner,404);
  else{
   var p=call("GET","/api/products/"+f[0],null,owner,200);var ss=p.path("details").path("sections");
   require(ss.size()==baseline.size()-(kind.equals("section")?1:0),"Expected surviving sections including automatically created Draft section");
   JsonNode targetSection=null;for(JsonNode section:ss)if(section.path("id").asText().equals(f[1]))targetSection=section;
   if(kind.equals("section"))require(targetSection==null,"Deleted section absent from parent");
   if(kind.equals("lesson"))require(targetSection!=null&&targetSection.path("lessons").size()==0,"Deleted lesson absent from parent");
   if(kind.equals("quiz"))require(targetSection!=null&&targetSection.path("lessons").size()==1,"Lesson retained after quiz deletion");
  }
 }
 void downloadDelete(String kind)throws Exception{
  var f=downloadFixture();String target="/api/products/"+f[0]+(kind.equals("product")?"":"/sections/"+f[1]+(kind.equals("file")?"/files/"+f[2]:""));
  call("DELETE",target,null,actor,204);require(count("files_download_products","id",f[2])==0,"File metadata gone");
  if(kind.equals("product"))call("GET","/api/products/"+f[0],null,owner,404);
  else{
   var p=call("GET","/api/products/"+f[0],null,owner,200);var ss=p.path("details").path("sections");
   require(ss.size()==(kind.equals("section")?0:1),"Expected surviving file groups");
   if(kind.equals("file"))require(ss.get(0).path("files").size()==0,"Deleted file absent from parent");
  }
 }
 void membershipDelete()throws Exception{
  String p=product("MEMBERSHIP","Cascade membership");List<String> ids=new ArrayList<>();
  for(String type:List.of("POST","VIDEO","RESOURCE")){
   Map<String,Object> body=new LinkedHashMap<>(Map.of("type",type,"title","Fixture "+type,"status","DRAFT","body","Synthetic body","description","Synthetic description"));
   if(!type.equals("POST"))body.put(type.equals("VIDEO")?"video":"file",Map.of("fileName",type.equals("VIDEO")?"fixture.mp4":"fixture.pdf","fileType",type.equals("VIDEO")?"video/mp4":"application/pdf","size",42));
   ids.add(call("POST","/api/products/"+p+"/membership/content",body,owner,201).path("id").asText());
  }
  require(call("GET","/api/products/"+p+"/membership",null,owner,200).path("feed").size()==3,"Three feed entries before deletion");
  for(String id:ids){
   call("DELETE","/api/products/"+p+"/membership/content/"+id,null,actor,204);
   var after=call("GET","/api/products/"+p+"/membership",null,owner,200);
   require(!after.path("content").toString().contains(id)&&!after.path("feed").toString().contains(id),"Deleted content/feed reference absent");
   require(count("membership_content","id",id)==0,"Native metadata gone");
  }
  call("POST","/api/products/"+p+"/membership/content",Map.of("type","POST","title","Remaining native","body","Fixture","status","DRAFT"),owner,201);
  call("DELETE","/api/products/"+p,null,actor,204);
  call("GET","/api/products/"+p+"/membership",null,owner,404);
  call("GET","/api/products/"+p,null,owner,404);
  require(count("membership_content","membership_product_id",p)==0,"Membership child metadata gone");
  require(count("membership_feed_entries","membership_product_id",p)==0,"Membership feed gone");
 }
 void includedReferenceDelete()throws Exception{
  String m=product("MEMBERSHIP","Included reference"),c=product("COURSE","Included course"),d=product("DOWNLOAD","Included download");
  call("PUT","/api/products/"+m+"/membership/feed",Map.of("orderingMode","MANUAL","feed",List.of(Map.of("kind","PRODUCT","productId",c),Map.of("kind","PRODUCT","productId",d))),owner,200);
  call("DELETE","/api/products/"+c,null,actor,204);
  var a=call("GET","/api/products/"+m+"/membership",null,owner,200);
  require(!a.path("feed").toString().contains(c)&&a.path("feed").toString().contains(d),"Only deleted included Course reference removed");
  call("DELETE","/api/products/"+d,null,actor,204);
  require(call("GET","/api/products/"+m+"/membership",null,owner,200).path("feed").size()==0,"Deleted included Download reference removed");
 }
 void historicalRetention()throws Exception{
  String[] f=courseFixture();String p=f[0];
  call("PATCH","/api/products/"+p,Map.of("price","25.00","status","PUBLISHED"),owner,200);
  var paid=call("POST","/api/commerce/checkout-sessions",Map.of("productIds",List.of(p)),buyer,201);
  String order=paid.path("orderId").asText();require(paid.path("status").asText().equals("PAID"),"Fake paid control");
  var refund=call("POST","/api/dev/commerce/orders/"+order+"/simulate",Map.of("outcome","REFUNDED"),admin,200);require(refund.path("status").asText().equals("REFUNDED"),"Refund before permitted deletion");
  var before=call("GET","/api/commerce/orders/"+order,null,buyer,200);
  var reportBefore=call("GET","/api/creator/orders/"+order,null,owner,200);
  call("DELETE","/api/products/"+p,null,actor,204);goneQuiz(f);
  call("GET","/api/products/"+p,null,owner,404);
  var after=call("GET","/api/commerce/orders/"+order,null,buyer,200);
  require(before.path("items").equals(after.path("items")),"Historical immutable buyer item snapshots unchanged");
  require(after.path("status").asText().equals("REFUNDED")&&after.path("totalMinor").asLong()==2500,"Historical refunded amount/status retained");
  var report=call("GET","/api/creator/orders/"+order,null,owner,200);
  require(report.path("items").get(0).path("product").equals(reportBefore.path("items").get(0).path("product")),"Creator historical identity snapshot retained");
  require(report.path("amountCents").asLong()==2500,"Creator report amount retained");
  var ledger=call("GET","/api/creator/orders?search="+order+"&period=90d",null,owner,200);
  require(ledger.path("content").size()==1&&ledger.path("content").get(0).path("id").asText().equals(order),"Historical creator ledger retained");
  require(count("commerce_order_items","product_id",p)==1,"Immutable financial item persists");
 }
 interface Checked{void run()throws Exception;}
 void scenario(String name,Checked action){current=(actor==admin?"ADMIN":"OWNER_CREATOR")+"-"+name;int start=observations.size();try{action.run();scenarios.add(Map.of("scenario",current,"status","Pass","http_observations",observations.size()-start));System.out.println(current+": PASS");}catch(Throwable t){scenarios.add(Map.of("scenario",current,"status","Fail","error",t.toString(),"http_observations",observations.size()-start));System.out.println(current+": FAIL "+t.getClass().getSimpleName());}}
 public static void main(String[] args)throws Exception{
  var test=new MigratedCascadeQa();var manager=new TestContextManager(MigratedCascadeQa.class);manager.prepareTestInstance(test);
  try{
   test.require(test.db.queryForObject("SELECT current_database()",String.class).equals("vpqa_cascades"),"Only disposable fixture database");
   int migrated=test.db.queryForObject("SELECT count(*) FROM databasechangelog",Integer.class);test.require(migrated==40,"All forty migrations run");
   test.owner=test.user("cascade-owner-corrected@example.invalid","CREATOR");test.admin=test.user("cascade-admin-corrected@example.invalid","ADMIN");test.buyer=test.user("cascade-buyer-corrected@example.invalid","USER");
   for(User actor:List.of(test.owner,test.admin)){
    test.actor=actor;
    if(args.length>0&&args[0].equals("corrected-course-recheck")){
     for(String kind:List.of("quiz","lesson","section"))test.scenario("course-"+kind+"-cascade",()->test.courseDelete(kind));
     continue;
    }
    for(String kind:List.of("quiz","lesson","section","product"))test.scenario("course-"+kind+"-cascade",()->test.courseDelete(kind));
    for(String kind:List.of("file","section","product"))test.scenario("download-"+kind+"-cascade",()->test.downloadDelete(kind));
    test.scenario("native-membership-metadata-cascade",test::membershipDelete);
    test.scenario("included-product-reference-cleanup",test::includedReferenceDelete);
    test.scenario("refunded-historical-order-retention",test::historicalRetention);
   }
   verifyNoInteractions(test.spaces,test.mail);
   var out=new LinkedHashMap<String,Object>();out.put("database","PostgreSQL15.19 disposable localhost cluster");out.put("migrations_applied",migrated);out.put("hibernate_ddl","none");out.put("scenarios",test.scenarios);out.put("observations",test.observations);out.put("external_mock_interactions",0);
   Files.writeString(Path.of(args.length>0?"/private/tmp/vpqa-pg-cascade-corrected-observations.json":"/private/tmp/vpqa-pg-cascade-observations.json"),test.mapper.writerWithDefaultPrettyPrinter().writeValueAsString(out));
   System.out.println("Recorded "+test.scenarios.size()+" scenarios and "+test.observations.size()+" actual HTTP observations");
  }finally{((ConfigurableApplicationContext)manager.getTestContext().getApplicationContext()).close();}
 }
}

