public class MigratedMediaOwnershipQa extends MigratedCascadeQa {
 User other;String principal;int uploadCalls=0,deleteCalls=0;byte[] png,mp4;List<Map<String,Object>> checks=new ArrayList<>();
 JsonNode request(String method,String path,Object json,byte[] bytes,String mime,User who,int expected)throws Exception{
  MockHttpServletRequestBuilder q=switch(method){case "POST"->post(path);case "PUT"->put(path);case "DELETE"->delete(path);default->get(path);};
  if(who!=null)q.cookie(new Cookie("JWT_TOKEN",jwt.generateToken(who)));if(!method.equals("GET"))q.cookie(new Cookie("XSRF-TOKEN",CSRF)).header("X-XSRF-TOKEN",CSRF);
  if(bytes!=null)q.contentType(mime).content(bytes);else if(json!=null)q.contentType("application/json").content(mapper.writeValueAsBytes(json));
  var resp=mvc.perform(q).andReturn().getResponse();String text=resp.getContentAsString();JsonNode body=text.isEmpty()?mapper.nullNode():(text.startsWith("{")||text.startsWith("["))?mapper.readTree(text):mapper.valueToTree(text);
  var o=new LinkedHashMap<String,Object>();o.put("scenario",current);o.put("method",method);o.put("path",path);o.put("actor",who==null?"GUEST":who==admin?"ADMIN":who==other?"NONOWNER_CREATOR":who==buyer?"USER":"OWNER_CREATOR");o.put("expected_status",expected);o.put("actual_status",resp.getStatus());o.put("body",body);if(bytes!=null){o.put("raw_bytes",bytes.length);o.put("mime",mime);}observations.add(o);
  require(expected==0?(resp.getStatus()==401||resp.getStatus()==403):resp.getStatus()==expected,"Expected "+(expected==0?"Guest denial401/403":expected)+", actual"+resp.getStatus());return body;
 }
 JsonNode read(String p)throws Exception{return request("GET","/api/products/"+p,null,null,null,owner,200);}
 JsonNode snapshot(JsonNode p){var o=mapper.createObjectNode();for(String key:List.of("imageUrl","galleryImages","promoVideo"))o.set(key,p.path(key));return o;}
 List<String> gallery(JsonNode p){var ids=new ArrayList<String>();for(JsonNode j:p.path("galleryImages"))ids.add(j.path("id").asText());return ids;}
 String thumb(String p){return "/api/products/image?productId="+p;}
 String media(String p,String suffix){return "/api/products/"+p+"/media/"+suffix;}
 void check(String name,String caseId,String p,Checked action){current=name;int start=observations.size();try{action.run();checks.add(Map.of("scenario",current,"case_id",caseId,"product_id",p,"status","Pass","http_observations",observations.size()-start));System.out.println(current+": PASS");}catch(Throwable t){checks.add(Map.of("scenario",current,"case_id",caseId,"product_id",p,"status","Fail","error",t.toString(),"http_observations",observations.size()-start));System.out.println(current+": FAIL "+t.getClass().getSimpleName());}finally{clearInvocations(spaces);}}
 void seed(String p)throws Exception{request("POST",thumb(p),null,png,"image/png",owner,200);request("POST",media(p,"gallery"),null,png,"image/png",owner,200);request("POST",media(p,"gallery"),null,png,"image/png",owner,200);request("POST",media(p,"promo-video"),null,mp4,"video/mp4",owner,200);}
 void matrix(String type,String label,User who)throws Exception{
  principal=label;current=label+"-"+type+"-fixture";String p=product(type,"Media permissions "+type);seed(p);
  for(String operation:List.of("thumbnail-post","thumbnail-delete","gallery-post","gallery-delete","gallery-order","promo-post","promo-delete"))check(label+"-"+type+"-"+operation,"MEDIA-011",p,()->{
   var before=read(p);int uploads=uploadCalls,deletes=deleteCalls;boolean allowed=who==owner||who==admin;String method=operation.endsWith("post")?"POST":operation.endsWith("delete")?"DELETE":"PUT";String path=operation.startsWith("thumbnail")?thumb(p):media(p,operation.startsWith("promo")?"promo-video":"gallery");Object json=null;byte[] bytes=null;String mime=null;
   if(method.equals("POST")){mime=operation.startsWith("promo")?"video/mp4":"image/png";bytes=operation.startsWith("promo")?mp4:png;}
   if(operation.equals("gallery-delete"))path+="/"+gallery(before).get(0);
   if(operation.equals("gallery-order")){path+="/order";json=Map.of("imageIds",gallery(before));}
   request(method,path,json,bytes,mime,who,allowed?(method.equals("DELETE")?204:200):who==null?0:403);var after=read(p);
   if(!allowed){require(snapshot(after).equals(snapshot(before)),"Denied request leaves exact media DTOs unchanged");require(uploadCalls==uploads&&deleteCalls==deletes,"Denied media endpoint never invokes storage");}
   else if(method.equals("POST")){require(uploadCalls==uploads+1,"Allowed POST reaches storage");require(!snapshot(after).equals(snapshot(before)),"Allowed POST persisted media mutation");}
   else if(method.equals("DELETE")){require(deleteCalls==deletes+1,"Allowed DELETE cleans one object");require(!snapshot(after).equals(snapshot(before)),"Allowed DELETE persisted metadata change");}
   else{require(snapshot(after).equals(snapshot(before)),"Valid unchanged complete order persists");require(uploadCalls==uploads&&deleteCalls==deletes,"Order metadata needs no storage");}
  });
 }
 void capacity(String type,User who)throws Exception{
  current=(who==admin?"ADMIN":"OWNER_CREATOR")+"-"+type+"-capacity-fixture";String p=product(type,"Gallery capacity "+type);for(int i=0;i<20;i++)request("POST",media(p,"gallery"),null,png,"image/png",who,200);
  check((who==admin?"ADMIN":"OWNER_CREATOR")+"-"+type+"-20-limit-remove-reupload","MEDIA-005",p,()->{var before=read(p);require(gallery(before).size()==20,"Twenty gallery entries before limit");int calls=uploadCalls;request("POST",media(p,"gallery"),null,png,"image/png",who,400);require(snapshot(read(p)).equals(snapshot(before))&&uploadCalls==calls,"21st rejected without metadata or storage");request("DELETE",media(p,"gallery")+"/"+gallery(before).get(0),null,null,null,who,204);var deleted=read(p);require(gallery(deleted).size()==19,"One slot freed");for(int i=0;i<19;i++)require(deleted.path("galleryImages").get(i).path("position").asInt()==i,"Contiguous remaining positions");request("POST",media(p,"gallery"),null,png,"image/png",who,200);var after=read(p);require(gallery(after).size()==20&&after.path("galleryImages").get(19).path("position").asInt()==19,"New upload occupies freed capacity");});
 }
 public static void main(String[] args)throws Exception{
  var t=new MigratedMediaOwnershipQa();var manager=new TestContextManager(MigratedMediaOwnershipQa.class);manager.prepareTestInstance(t);
  try{
   t.require(t.db.queryForObject("SELECT current_database()",String.class).equals("vpqa_cascades"),"Only private fixture database");t.require(t.db.queryForObject("SELECT count(*) FROM databasechangelog",Integer.class)==40,"All40 migrations");t.png=Files.readAllBytes(Path.of("/private/tmp/vpqa-media-validation-fixtures/image.png"));t.mp4=Files.readAllBytes(Path.of("/private/tmp/vpqa-media-validation-fixtures/video.mp4"));
   t.owner=t.user("media-permission-owner@example.invalid","CREATOR");t.admin=t.user("media-permission-admin@example.invalid","ADMIN");t.other=t.user("media-permission-nonowner@example.invalid","CREATOR");t.buyer=t.user("media-permission-user@example.invalid","USER");
   doAnswer(i->{t.uploadCalls++;var body=(java.io.InputStream)i.getArgument(1);t.require(body.transferTo(java.io.OutputStream.nullOutputStream())==((Long)i.getArgument(2)),"Exact upload bytes reach mock adapter");return null;}).when(t.spaces).upload(anyString(),any(),anyLong(),anyString());doAnswer(i->{t.deleteCalls++;return null;}).when(t.spaces).delete(anyString());
   for(String type:List.of("COURSE","DOWNLOAD","CONSULTATION","MEMBERSHIP")){t.matrix(type,"OWNER_CREATOR",t.owner);t.matrix(type,"ADMIN",t.admin);t.matrix(type,"NONOWNER_CREATOR",t.other);t.matrix(type,"USER",t.buyer);t.matrix(type,"GUEST",null);t.capacity(type,t.owner);t.capacity(type,t.admin);}
   verifyNoInteractions(t.mail);var out=new LinkedHashMap<String,Object>();out.put("database","PostgreSQL15.19 private migrated fixture");out.put("migrations_applied",40);out.put("hibernate_ddl","none");out.put("scenarios",t.checks);out.put("observations",t.observations);out.put("real_external_requests",0);out.put("mock_upload_calls",t.uploadCalls);out.put("mock_delete_calls",t.deleteCalls);
   Files.writeString(Path.of("/private/tmp/vpqa-pg-media-ownership-observations.json"),t.mapper.writerWithDefaultPrettyPrinter().writeValueAsString(out));System.out.println("Recorded "+t.checks.size()+" assessments and "+t.observations.size()+" HTTP observations");
  }finally{((ConfigurableApplicationContext)manager.getTestContext().getApplicationContext()).close();}
 }
}

