  try{
   t.require(t.db.queryForObject("SELECT current_database()",String.class).equals("vpqa_cascades"),"Private database only");
   t.require(t.db.queryForObject("SELECT count(*) FROM databasechangelog",Integer.class)==40,"All migrations");
   t.owner=t.user("transport-owner@example.invalid","CREATOR");t.png=Files.readAllBytes(Path.of("/private/tmp/vpqa-media-validation-fixtures/image.png"));t.mp4=Files.readAllBytes(Path.of("/private/tmp/vpqa-media-validation-fixtures/video.mp4"));
   String p=t.product("COURSE","Synthetic transport contract");
