    t.checks.add(Map.of("case_id","MEDIA-003","scenario",t.current,"status","Pass","product_id",p,"http_observations",3));
   }
   Files.writeString(Path.of("/private/tmp/vpqa-pg-media-transport-observations.json"),t.mapper.writerWithDefaultPrettyPrinter().writeValueAsString(Map.of("scenarios",t.checks,"observations",t.observations,"real_external_requests",0,"migrations_applied",40)));
   System.out.println("Three application/json MIME rejections confirmed; exact metadata unchanged; no storage calls");
  }finally{((ConfigurableApplicationContext)manager.getTestContext().getApplicationContext()).close();}
 }
}

