 void historicalRetention()throws Exception{
  String[] f=courseFixture();String p=f[0];
  call("PATCH","/api/products/"+p,Map.of("price","25.00","status","PUBLISHED"),owner,200);
  var paid=call("POST","/api/commerce/checkout-sessions",Map.of("productIds",List.of(p)),buyer,201);
  String order=paid.path("orderId").asText();require(paid.path("status").asText().equals("PAID"),"Fake paid control");
  var refund=call("POST","/api/dev/commerce/orders/"+order+"/simulate",Map.of("outcome","REFUNDED"),admin,200);require(refund.path("status").asText().equals("REFUNDED"),"Refund before permitted deletion");
  var before=call("GET","/api/commerce/orders/"+order,null,buyer,200);
  var reportBefore=call("GET","/api/creator/orders/"+order,null,owner,200);
  call("DELETE","/api/products/"+p,null,actor,204);goneQuiz(f);
  call("GET","/api/products/"+p,null,owner,404);
  var after=call("GET","/api/commerce/orders/"+order,null,buyer,200);
  require(before.path("items").equals(after.path("items")),"Historical immutable buyer item snapshots unchanged");
  require(after.path("status").asText().equals("REFUNDED")&&after.path("totalMinor").asLong()==2500,"Historical refunded amount/status retained");
  var report=call("GET","/api/creator/orders/"+order,null,owner,200);
  require(report.path("items").get(0).path("product").equals(reportBefore.path("items").get(0).path("product")),"Creator historical identity snapshot retained");
  require(report.path("amountCents").asLong()==2500,"Creator report amount retained");
  var ledger=call("GET","/api/creator/orders?search="+order+"&period=90d",null,owner,200);
  require(ledger.path("content").size()==1&&ledger.path("content").get(0).path("id").asText().equals(order),"Historical creator ledger retained");
  require(count("commerce_order_items","product_id",p)==1,"Immutable financial item persists");
