 interface Checked{void run()throws Exception;}
 void scenario(String name,Checked action){current=(actor==admin?"ADMIN":"OWNER_CREATOR")+"-"+name;int start=observations.size();try{action.run();scenarios.add(Map.of("scenario",current,"status","Pass","http_observations",observations.size()-start));System.out.println(current+": PASS");}catch(Throwable t){scenarios.add(Map.of("scenario",current,"status","Fail","error",t.toString(),"http_observations",observations.size()-start));System.out.println(current+": FAIL "+t.getClass().getSimpleName());}}
 public static void main(String[] args)throws Exception{
  var test=new MigratedCascadeQa();var manager=new TestContextManager(MigratedCascadeQa.class);manager.prepareTestInstance(test);
  try{
   test.require(test.db.queryForObject("SELECT current_database()",String.class).equals("vpqa_cascades"),"Only disposable fixture database");
   int migrated=test.db.queryForObject("SELECT count(*) FROM databasechangelog",Integer.class);test.require(migrated==40,"All forty migrations run");
   test.owner=test.user("cascade-owner-corrected@example.invalid","CREATOR");test.admin=test.user("cascade-admin-corrected@example.invalid","ADMIN");test.buyer=test.user("cascade-buyer-corrected@example.invalid","USER");
   for(User actor:List.of(test.owner,test.admin)){
    test.actor=actor;
    if(args.length>0&&args[0].equals("corrected-course-recheck")){
     for(String kind:List.of("quiz","lesson","section"))test.scenario("course-"+kind+"-cascade",()->test.courseDelete(kind));
     continue;
    }
    for(String kind:List.of("quiz","lesson","section","product"))test.scenario("course-"+kind+"-cascade",()->test.courseDelete(kind));
    for(String kind:List.of("file","section","product"))test.scenario("download-"+kind+"-cascade",()->test.downloadDelete(kind));
    test.scenario("native-membership-metadata-cascade",test::membershipDelete);
    test.scenario("included-product-reference-cleanup",test::includedReferenceDelete);
    test.scenario("refunded-historical-order-retention",test::historicalRetention);
   }
   verifyNoInteractions(test.spaces,test.mail);
   var out=new LinkedHashMap<String,Object>();out.put("database","PostgreSQL15.19 disposable localhost cluster");out.put("migrations_applied",migrated);out.put("hibernate_ddl","none");out.put("scenarios",test.scenarios);out.put("observations",test.observations);out.put("external_mock_interactions",0);
   Files.writeString(Path.of(args.length>0?"/private/tmp/vpqa-pg-cascade-corrected-observations.json":"/private/tmp/vpqa-pg-cascade-observations.json"),test.mapper.writerWithDefaultPrettyPrinter().writeValueAsString(out));
   System.out.println("Recorded "+test.scenarios.size()+" scenarios and "+test.observations.size()+" actual HTTP observations");
  }finally{((ConfigurableApplicationContext)manager.getTestContext().getApplicationContext()).close();}
 }
